    'framework_1bab34a975fe' => 'Lipulla saa olla enintään :limit käyttäjä- ja organisaatiosääntöä. Kohdista se organisaatioon tai käytä prosenttiosuutta sen sijaan, että luettelisit jokaisen käyttäjän.',
