    'framework_7f141d42c02f' => ':where perii relaation `:value2` kautta. Sen on oltava yksinkertainen tyyppiluettelo, kuten `[folder]`, eikä sitä saa laskea muista relaatioista.',
    'framework_8038ba872fa4' => 'Käyttöoikeusalue [:key] ei ole kelvollinen (RFC 6749 §3.3: enintään 128 tulostettavaa ASCII-merkkiä, ei välilyöntejä, lainausmerkkejä eikä kenoviivoja).',
