    'framework_918e4c13cded' => 'Valtuutuspalvelin määrittää käyttöoikeusalueen [:key] itse, joten se ei voi kuulua APIin.',
    'framework_92967f0779d6' => 'Lipun avaimessa [:key] on oltava 1–64 merkkiä: pieniä kirjaimia ja numeroita sekä niiden välissä merkkejä `-`, `_` tai `.`.',
