    'framework_aeb6433c3c63' => '`:value1` tyypissä `:value2` vähentää kohteen `:target`, joka riippuu relaatiosta `:self` itsestään. Poissulkeminen ei saa viitata takaisin määrittämäänsä relaatioon.',
