    'this_idempotency_key_was_already_used_for_a_different_r_0c304fb5' => 'Tätä Idempotency-Key-avainta on jo käytetty toiseen pyyntöön. Käytä uuteen pyyntöön uutta avainta.',
    'this_is_exactly_how_your_sign_in_renders_the_preview_sh_a4878600' => 'Tältä kirjautumissivusi todella näyttää. Esikatselu käyttää samaa teemojen käsittelyä kuin varsinainen sivu.',
    'this_is_the_app_s_only_live_secret_rotate_it_to_replace_70716789' => 'Tämä on sovelluksen ainoa aktiivinen salaisuus. Vaihda se uusimalla tai sammuta sovellus poistamalla se.',
    'this_is_the_app_s_only_live_secret_so_it_cannot_be_revo_d05986bb' => 'Tämä on sovelluksen ainoa aktiivinen salaisuus, joten sitä ei voi perua yksinään ilman korvaavaa salaisuutta. Uusi se sen sijaan.',
    'this_is_your_environment_s_default_sign_in_an_organizat_d17d58dd' => 'Tämä on ympäristön oletuskirjautumissivu. Organisaatio voi korvata sen omalla teemallaan.',
    'this_organization_owns_identity_provider_projects_on_th_f851615d' => 'Organisaatio omistaa identiteettipalveluprojekteja tällä alustalla, joten sitä ei voi arkistoida täällä.',
    'this_organization_owns_identity_providers_on_this_platf_f47c5479' => 'Organisaatio omistaa identiteettipalveluita tällä alustalla. Sulje ensin sen projektit kohdassa Organisaatio › Projektit.',
    'this_organization_s_brand_it_overrides_the_environment_ffdddbcc' => 'Organisaation oma brändi korvaa ympäristön oletuksen. Muutokset näkyvät heti esikatselussa ja koskevat sen ylläpidettyä kirjautumissivua.',
    'this_organization_s_own_authentication_policy_is_droppe_a12f3b55' => 'Organisaation oma tunnistautumiskäytäntö poistetaan. Tästä lähtien siihen sovelletaan ympäristön perussääntöjä.',
    'this_permission_is_removed_from_every_role_that_current_d88d6738' => 'Käyttöoikeus poistetaan kaikista rooleista, jotka sen tällä hetkellä myöntävät. Tätä ei voi perua.',
    'this_provider_s_discovery_document_publishes_no_signing_07a38178' => 'Palveluntarjoajan discovery-asiakirja ei julkaise allekirjoitusavaimia (jwks_uri). Liitä ID-tunnisteen allekirjoittamiseen käytetty julkinen PEM-avain.',
    'this_role_belongs_to_the_environment_and_applies_across_0a2b2ed6' => 'Rooli kuuluu ympäristölle ja koskee sen kaikkia organisaatioita. Se on voimassa täällä, mutta et voi muuttaa sitä.',
    'this_role_grants_no_permissions_the_application_that_de_59b043d0' => 'Rooli ei myönnä käyttöoikeuksia. Sen määrittävä sovellus päättää, mitä rooli sallii.',
    'this_role_is_declared_by_an_application_which_is_its_so_03e7843e' => 'Roolin määrittää sovellus, joka on sen määräävä lähde. Roolia ei voi muokata täällä.',
    'this_rule_binds_every_organization_here_choose_one_in_t_9d1bbde3' => 'Sääntö koskee kaikkia organisaatioita täällä. Valitse organisaatio hallintakonsolin yläpalkista sen määritysten tarkistamiseksi.',
    'this_rule_binds_every_organization_in_the_environment_i_91928f48' => 'Sääntö koskee kaikkia ympäristön organisaatioita. Se näkyy tässä, koska se rajoittaa myös omaa organisaatiotasi. Operaattorisi hallinnoi sitä.',
    'this_user_is_held_at_a_password_change_they_cannot_reac_ce196382' => 'Käyttäjän on vaihdettava salasana. Hän ei pääse eteenpäin ennen myöntämäsi salasanan korvaamista.',
    'to_register_an_api_for_one_organization_find_it_here_it_48b04329' => 'Etsi organisaatio tästä rekisteröidäksesi APIn sille. Sen jälkeen voit valita sen yllä omistajaksi.',
    'user_erased_their_account_is_pseudonymised_and_the_eras_51e1f69a' => 'Käyttäjä poistettu. Tili on pseudonymisoitu, ja poisto on kirjattu tapahtumalokiin nimellä user.erased.',
    'valid_once_and_short_lived_turn_this_off_only_if_you_ar_521114e3' => 'Voimassa kerran ja lyhyen ajan. Poista tämä käytöstä vain, jos luot tilin etukäteen ja lähetät linkin itse.',
    'verify_that_authnrequests_really_come_from_this_applica_f3c58c70' => 'Varmista sovelluksen omalla allekirjoitusvarmenteella, että AuthnRequests-pyynnöt todella tulevat siltä.',
    'verify_the_domain_before_turning_capture_on_until_then_4ff9f310' => 'Vahvista verkkotunnus ennen SSO-reitityksen käyttöönottoa. Siihen asti organisaatio ei ole osoittanut hallitsevansa näitä osoitteita.',
    'verify_the_email_domains_you_own_so_your_people_are_rou_3f6d7cfe' => 'Vahvista omistamasi sähköpostiverkkotunnukset, jotta käyttäjät ohjataan automaattisesti palveluntarjoajallesi.',
    'verify_the_signature_on_every_call_and_answer_within_th_5219ed81' => 'Tarkista jokaisen kutsun allekirjoitus ja vastaa aikarajan sisällä. Toiminto suoritetaan käyttäjän odottaessa kirjautumissivulla.',
    'we_could_not_send_that_invitation_the_mail_server_refus_81a3f4df' => 'Kutsua ei voitu lähettää, koska sähköpostipalvelin hylkäsi sen. Mitään ei luotu. Yritä uudelleen tai tarkista asennuksen sähköpostiasetukset.',
    'webhook_id_webhook_timestamp_and_webhook_signature_with_73e511b0' => 'webhook-id, webhook-timestamp ja webhook-signature whsec_-salaisuudella. Ne voi tarkistaa millä tahansa Standard Webhooks -kirjastolla.',
    'what_people_can_do_inside_your_apps_you_assign_roles_he_c31f1a20' => 'Mitä henkilöt voivat tehdä sovelluksissasi. Myönnät roolit täällä, ja kukin sovellus määrittää, mitä sen roolit sallivat.',
    'what_this_round_is_called_when_somebody_asks_which_revi_6e0713c0' => 'Tarkistuskierroksen nimi, kun joku kysyy, mistä tarkistuksesta päätös on peräisin, esimerkiksi vuosineljännes, auditointi tai päivämäärä.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_789a1199' => 'Kaikki, mihin haltija käyttää tätä avainta, lakkaa toimimasta heti. Tätä ei voi perua.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_e14495d2' => 'Kaikki, mihin haltija käyttää tätä avainta, lakkaa toimimasta heti. Ilmoita hänelle etukäteen, jos mahdollista. Tätä ei voi perua.',
    'when_an_app_or_agent_needs_your_go_ahead_to_act_as_you_3a85a2a9' => 'Kun sovellus tai agentti tarvitsee hyväksyntäsi toimiakseen nimissäsi, se pyytää sitä tässä. Hyväksy vain itse aloittamasi pyynnöt.',
    'when_somebody_creates_an_api_key_for_one_of_your_apps_i_15c6370c' => 'Kun joku luo API-avaimen sovelluksellesi, se näkyy tässä haltijan ja käyttöoikeuksien kanssa.',
    'whether_the_background_work_of_this_install_webhooks_si_0647da12' => 'Lähetetäänkö asennuksen taustatyöt todella: webhookit, uloskirjautumisilmoitukset yhdistetyille sovelluksille ja jonotetut sähköpostit.',
    'which_headers_every_delivery_carries_changing_it_issues_5a2ff32e' => 'Kunkin toimituksen sisältämät otsakkeet. Muutos ei luo uutta salaisuutta; nykyistä käytetään allekirjoittamiseen kummassakin tapauksessa.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Ketkä kuuluvat organisaatioon ja mitä he voivat tehdä. Henkilöt, joilla ei vielä ole tiliä, kutsutaan sähköpostitse.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Kuka saa lipun, jos mikään sääntö ei nimeä häntä. Jätä pois käytöstä, jos haluat ottaa toiminnon ensin käyttöön valituille organisaatioille tai prosenttiosuudelle käyttäjistä.',
    'who_is_signed_in_as_them_right_now_why_a_sign_in_was_al_181f0520' => 'Kuka on parhaillaan kirjautuneena henkilönä. Radar kertoo, miksi kirjautuminen sallittiin, lisävarmennettiin tai estettiin.',
    'whose_people_sign_in_through_it_its_domains_and_admin_p_9c461a3e' => 'Organisaatio, jonka käyttäjät kirjautuvat yhteyden kautta. Sen verkkotunnukset ja ylläpitoportaalin linkki löytyvät organisaation sivulta.',
    'withdrawn_people_already_migrated_are_unaffected_anyone_228f7b22' => 'Peruttu. Jo siirretyt käyttäjät eivät muutu, mutta vanhassa järjestelmässä olevat eivät voi kirjautua.',
    'organization_suspended_its_members_can_no_longer_sign_i_35d8877a' => 'Organisaatio on keskeytetty. Sen jäsenet eivät voi enää kirjautua, eivätkä sen ympäristöt käsittele tunnistautumista.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Luoda, järjestää ja poistaa Radar-sääntöjä, muokata sisäisiä sääntöjä sekä lisätä ja poistaa sallittujen ja estettyjen luetteloiden merkintöjä.',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'Olet ainoa omistaja. Siirrä ensin omistajuus toiselle henkilölle tai poista organisaatio.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'Voit palata milloin tahansa asetukseen ”Suosi SSO:ta” tai ”Molemmat käytettävissä”. Päätetyt istunnot pysyvät päättyneinä.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Menetät pääsyn organisaatioon ja sen sovelluksiin heti. Ylläpitäjä voi kutsua sinut takaisin.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Tarvitset oman palveluntarjoajatilisi tunnukset, yleensä asiakastunnuksen ja salaisuuden. Apple myöntää niiden sijaan allekirjoitusavaimen.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'Tunnistautumiskäytäntösi on edelleen voimassa: salasanan vahvuus, vuototarkistus, sähköpostin vahvistus, pyyntörajat ja bottitarkistukset.',
    'your_endpoint_is_called_in_the_middle_of_an_operation_a_ab67a6b0' => 'Päätepistettäsi kutsutaan kesken toiminnon, ja sen vastaus vaikuttaa tulokseen esimerkiksi lisäämällä tunnisteeseen tietoja tai estämällä kirjautumisen.',
    'your_endpoints_get_a_signed_message_after_something_hap_04723db4' => 'Päätepisteesi saavat allekirjoitetun viestin tapahtuman jälkeen, jotta järjestelmäsi voivat reagoida ilman jatkuvaa kyselyä.',
    'your_hr_system_people_get_an_account_on_their_start_dat_6be42da6' => 'HR-järjestelmäsi: henkilöt saavat tilin ensimmäisenä työpäivänään ja menettävät pääsyn viimeisen päivän jälkeen.',
    'your_organization_s_name_domains_and_defaults_changes_h_8e3220c0' => 'Organisaation nimi, verkkotunnukset ja oletusasetukset. Muutokset koskevat kaikkia organisaation kautta kirjautuvia.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Oma APIsi. Päätät jokaisesta käyttöoikeusalueesta, saavatko organisaatioiden rekisteröimät sovellukset pyytää sitä.',
    'your_own_credentials_with_each_provider_offered_on_ever_82ce1e08' => 'Omat tunnuksesi kullekin palveluntarjoajalle, tarjolla ympäristön kaikilla kirjautumissivuilla. Kaikki organisaatiot perivät ne.',
    'your_own_credentials_with_each_provider_offered_to_ever_d1715d1a' => 'Omat tunnuksesi kullekin palveluntarjoajalle, tarjolla kaikille ympäristössä. Jokainen organisaatio perii ne.',
    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'Vastaanottaja säilyttää saman salaisuuden ja käyttää sitä muuttamattomana whsec_-etuliitteineen X-Cbox-Signature-otsakkeen HMAC-avaimena.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Kirjautumissivulla on oma logosi ja värisi. Käyttäjät kirjoittavat siihen salasanansa, joten sivun tulee näyttää selvästi sinun palvelultasi.',
    'your_organization_its_projects_team_keys_and_billing_si_152a2f42' => 'Organisaatiosi projektit, tiimi, avaimet ja laskutus. Sovellusten kirjautuminen määritetään kunkin ympäristön hallintakonsolissa.',
    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Toimintolippu on asetus, jota sovellukset kysyvät tietylle henkilölle tietyssä organisaatiossa. Ota se käyttöön valituille käyttäjille, organisaatioille tai prosenttiosuudelle kaikista. Kaikki sovellukset saavat saman vastauksen tunnisteen `feature_flags`-claimista tai arviointipäätepisteestä ilman uutta julkaisua. Käyttäjäsääntö ohittaa organisaatiosäännön, joka ohittaa asteittaisen käyttöönoton, joka ohittaa oletuksen.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Avaimella komentosarjasi ja integraatiosi voivat kutsua sovelluksen APIa nimissäsi ilman kirjautumista. Avain voi tehdä vain sen, mihin sinulla on oikeus sovelluksessa. Jos oikeuksiasi vähennetään, avain menettää samat oikeudet. Avain näytetään kerran, joten kopioi se luodessasi ja peru se heti, jos se paljastuu tai jää käyttämättä.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Käyttöoikeus sallii roolille yhden toiminnon, kuten laskujen luomisen tai raporttien lukemisen. Voit määrittää täällä omia oikeuksia ilman koodia ja koota niistä rooleja. Sovellukset voivat myös rekisteröidä omansa automaattisesti, jolloin luettelo vastaa sovelluksen todellisia tarkistuksia. Omia oikeuksia voit muuttaa; ympäristön jakamia voit käyttää mutta et muuttaa.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Tunnistautumissovelluksen sisältävä puhelin vastaa hyväksyntäpyyntöihin ja ilmoittaa kirjautumisista nimissäsi. Rekisteröi se skannaamalla koodi. Jos kadotat puhelimen, poista se heti tästä, jotta sillä ei voi enää hyväksyä mitään.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'Projekti on organisaation omistama identiteettipalvelutuote, johon ympäristöt kuuluvat. Ennen kuin organisaatio luo projektin omassa hallintakonsolissaan, täällä ei ole mitään valittavaa tai avattavaa. Tämä sivu ei luo projektia organisaation puolesta.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Projekti on yksi tuotteistasi, jolla on oma tilaus, kirjautuminen ja ympäristöt, kuten tuotanto ja staging. Avaa ympäristö täältä hallintaa varten. Luo uusi projekti, kun julkaiset tuotteen, jota on tarkoitus käyttää ja laskuttaa erikseen.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Rooli on sovellusten ymmärtämä tehtävä, kuten toimittaja tai tukihenkilö. Päätät täällä, kenellä on mikäkin rooli, ja kukin sovellus määrittää rooliensa oikeudet. Roolit seuraavat henkilöä yhdistettyihin sovelluksiin, joten voit myöntää ja perua pääsyn yhdessä paikassa.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Tarkistuksessa käyt läpi, kenellä on mikäkin rooli ja tarvitaanko sitä yhä. Oikeuksia kertyy huomaamatta, kun henkilöt vaihtavat tiimiä mutta säilyttävät vanhat oikeutensa. Tarkistus auttaa siivoamaan ne. Perumiset toteutetaan tarkistuksen sulkemisen yhteydessä, ja koko kierros tallennetaan auditointia varten.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Skeema määrittää, miltä toiminnon tapahtumien tulee näyttää: kohdetyypit ja metatiedot. Skeemalliset tapahtumat tarkistetaan saapuessa. Ilman skeemaa ne hyväksytään sellaisinaan, ellei tiukka tila ole käytössä.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Organisaatio on rekisteröityneen yrityksen alue tässä asennuksessa. Se sisältää projektit, ympäristöt ja tiimin. Avaa se tuotteiden ja ympäristöjen hallintaan. Keskeyttäminen kirjaa jäsenet ulos ja pysäyttää kirjautumiset kaikissa sen ympäristöissä.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Käyttöoikeuksia kertyy. Henkilöt vaihtavat tiimiä mutta säilyttävät vanhat oikeudet, kunnes auditoija kysyy niistä. Tarkistus tallentaa nykyiset määritykset ja edellyttää jokaisesta päätöstä, tarvitaanko sitä edelleen.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Lisää henkilö alla olevaan organisaatioon myöntääksesi pääsyn sinne. Jos sovelluksillasi ei ole omia asiakaskohtaisia alueita, voit antaa sen sijaan koko ympäristön kattavan ylläpito- ja tukiroolin.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Ylläpito- ja tukirooli myönnetään omille työntekijöille, kuten tuelle ja operoinnille, koko ympäristöön. Se on voimassa kaikissa organisaatioissa, eivätkä niiden ylläpitäjät voi nähdä, myöntää tai poistaa sitä. Näin myönnetty sovelluksen rooli koskee silti vain kyseistä sovellusta.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Ylläpito- ja tukirooli myönnetään omille työntekijöille koko ympäristöön. Se on voimassa kaikissa organisaatioissa, eivätkä niiden ylläpitäjät voi nähdä tai muuttaa sitä.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Agentti on ohjelmisto, joka toimii ympäristössä hallinta-avaimella: tekoälyavustaja kuten Claude Code tai Cursor, sisäinen botti tai oma taustapalvelusi. Anna jokaiselle oma avain vain tarvittavilla käyttöoikeusalueilla. Päätä hyväksyntääsi vaativat toimet ja peru avain heti työn päätyttyä tai jos jokin vaikuttaa epäilyttävältä.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'API on palvelusi, joka vastaanottaa pääsytunnisteita, esimerkiksi https://api.example.com. Rekisteröi se sen ymmärtämillä käyttöoikeusalueilla. Päätät, mitä niistä organisaatioiden rekisteröimät sovellukset saavat pyytää. APIlle tarkoitettu tunniste nimeää sen osoitteen vastaanottajaksi, jonka palvelusi tarkistaa.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Ympäristö on täysin eristetty identiteettipalvelu, jolla on omat käyttäjät, avaimet, kirjautuminen ja myöntäjä. Tässä näkyvät kaikki asennuksen ympäristöt ja niiden organisaatiot. Luo ympäristö, valitse se hallintakonsolissa ja määritä ensimmäinen organisaatio ja ylläpitäjä.',
    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'Ympäristö on täysin eristetty, ja sillä on omat käyttäjät, avaimet, kirjautuminen ja myöntäjä. Luo ensimmäinen ympäristö yllä ja määritä sille sitten organisaatio ja ylläpitäjä.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Palveluntarjoajan metatietoja tuova identiteettipalvelu käyttää tätä URLia erillisen entiteettitunnuksen ja ACS-URLin sijaan. Se toimii jo ennen identiteettipalvelun tietojen täydentämistä.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Organisaatio kokoaa käyttäjät, kirjautumistavat ja roolit. Luo organisaatio yllä tai määritä ympäristön ensimmäinen organisaatio ja ylläpitäjä Ympäristöt-sivulta.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Organisaation oma kirjautumispalvelu korvaa ympäristön palvelun sen kirjautumissivulla. Myös ympäristön palvelun käytöstä poistaneet organisaatiot näkyvät luettelossa. Käytöstä poisto piilottaa vain painikkeen; SSO-pakko estää muut kirjautumistavat.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'Sovellusten ja agenttien tarvitsemat ulkoisten palvelujen API-avaimet ja tunnisteet tallennetaan salattuina tänne sovelluskohtaisten asetusten sijaan. Lisää salaisuus kerran ja anna valituille sovelluksille oikeus käyttää sitä. Sitä ei enää näytetä, joten uusi se, jos kadotat sen.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'API-avaimet, joita sovelluksesi ja agenttisi käyttävät muissa palveluissa. Jokainen arvo tallennetaan salattuna, annetaan vain erikseen valtuutetuille sovelluksille eikä sitä enää näytetä tallennuksen jälkeen.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Sovellukset, jotka pyytävät toimia käyttäjiesi puolesta. Kukin käyttäjä hyväksyy omat pyyntönsä. Hylkää täällä vain epäilyttävältä vaikuttavat pyynnöt. Hylkäys kirjataan tapahtumalokiin.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Omia käyttäjäluetteloita ylläpitävät sovellukset jäävät jälkeen heti, kun joku liittyy tai lähtee. SCIM-yhteys välittää jokaisen muutoksen heti, myös helposti unohtuvat poistumiset.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID lähettää allekirjoitetun viestin päätepisteeseesi tapahtuman, kuten uuden jäsenen tai roolimuutoksen, jälkeen. Järjestelmäsi voivat reagoida ilman jatkuvaa kyselyä. Toimitusta yritetään tarvittaessa uudelleen. Päätepiste saa tiedon jälkikäteen eikä voi vaikuttaa tapahtumaan.',
    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Vahvista edelleen tarvittavat oikeudet ja peru muut. Mitään ei toteuteta ennen tarkistuksen sulkemista. Peruttu ylläpito- ja tukirooli poistuu silloin kaikista organisaatioista kerralla.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Valitse SCIM, jos palveluntarjoaja lähettää tiedot meille, Google Workspace tai Entra, jos meidän tulee noutaa ne, tai HR-järjestelmäsi, kuten Workday, BambooHR, Rippling, HiBob tai Personio, jotta tilit syntyvät aloituspäivänä.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code avaa selaimen kirjautumista varten ja kysyy, mitä sallit. Säilytettävää avainta ei tarvita. Kaikki OAuth-kirjautumista käyttävät MCP-asiakkaat toimivat samalla tavalla tällä URLilla.',
    'comma_or_space_separated_a_scope_you_type_is_unowned_it_c5513416' => 'Erottele pilkuilla tai välilyönneillä. Kirjoitetulla käyttöoikeusalueella ei ole API-omistajaa, ja se siirtyy sellaisenaan sovelluksen tunnisteisiin. Se ei voi nimetä rekisteröityä APIa vastaanottajaksi. Käytä niihin yllä olevia luetteloita.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Luoda, muuttaa, ottaa käyttöön, poistaa käytöstä ja poistaa SSO-yhteyksiä, vaatia SSO:ta organisaatiolta sekä vahvistaa ja ottaa käyttöön sen sähköpostiverkkotunnusten SSO-reititys. Muuttaa käyttäjien kirjautumista.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Luo organisaation, sen omistajan, ensimmäisen tuotteen ja tuotteen tuotantoympäristön. Omistaja saa sähköpostitse linkin oman salasanan määrittämiseen. Et valitse salasanaa hänen puolestaan.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Määrittää, korvata ja poistaa tapahtumalokin tapahtumien tarkistusskeemoja sekä muuttaa säilytysaikaa. Säilytysajan lyhentäminen poistaa vanhemmat tapahtumat pysyvästi.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Organisaation poistaminen poistaa kaikki sen projektit ja ympäristöt. Aktiivisten identiteettipalvelujen suojaamiseksi tätä ei voi tehdä itse. Ota yhteyttä tukeen jatkaaksesi.',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Jokainen organisaatio on tuotettasi käyttävä yritys tai tiimi, jolla on omat jäsenet, roolit, verkkotunnukset ja SSO. Luo yksi kullekin rekisteröityvälle yritykselle. Avaa organisaatio jäsenten, kutsujen ja vahvistettujen verkkotunnusten hallintaan tai keskeyttääksesi sen.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Jokainen putki antaa henkilöiden yhdistää oman tilinsä esimerkiksi GitHubiin, Googleen tai Slackiin. Tunnisteet säilytetään täällä salattuina ja ajan tasalla. Valtuutetut sovellukset pyytävät toimivan tunnisteen kutsuessaan palvelua henkilön nimissä eivätkä tallenna tunnistetta itse.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Organisaation jokaisella projektilla on oma tilaus ja ympäristökiintiö. Ne näkyvät tämän kuun käytön rinnalla: organisaatiot, laskutettavat SSO-yhteydet ja kirjautumiset. Hinnoittelu perustuu kuukausittain aktiivisiin käyttäjiin ja yritysyhteyksiin, kuten SSO ja SCIM. Hiekkalaatikkoympäristöistä ei peritä yhteysmaksua.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Koko ympäristö: kuka tahansa ympäristön tilin omistava voi kirjautua sovellukseen organisaatiosta riippumatta. Valitse organisaatio, jos et tarkoita tätä.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Poistaa henkilö pysyvästi (GDPR 17 artikla): tunnukset, istunnot, jäsenyydet ja henkilötiedot poistetaan, ja tili pseudonymisoidaan. Tätä ei voi perua.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Arviointijärjestys: estoluettelo, sallittujen luettelo, omat säännöt ylhäältä alkaen ensimmäisen osuman ratkaistessa, sitten sisäiset säännöt, joista tiukin osuma ratkaisee. Ilman osumaa pääsy sallitaan.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Jokainen toiminto hyväksytään sellaisena kuin sovellus lähettää sen. Lisää skeema, jotta sen tapahtumat tarkistetaan saapuessa. Lokin yhdenmukaisuus varmistetaan tapahtumaa kirjoitettaessa, ei vasta luettaessa.',
    'every_administrative_change_members_roles_connections_a_ef641619' => 'Jokainen jäseniin, rooleihin, yhteyksiin ja sovelluksiin tehty hallintamuutos tallentuu tähän heti tekijän ja ajankohdan kanssa. Erillisiä asetuksia ei tarvita.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Sovellusasetuksiin tai ympäristötiedostoihin tallennettuja API-avaimia ei voi uusia keskitetysti tai perua nopeasti. Täällä ne säilytetään salattuina, myönnetään sovelluskohtaisesti ja perutaan yhdellä napsautuksella.',
    'every_api_key_the_people_in_this_organization_have_crea_b802c1e7' => 'Kaikki API-avaimet, jotka organisaation henkilöt ovat luoneet sen sovelluksille. Peru paljastuneet tai käyttämättömät avaimet. Käyttäjät luovat omat avaimensa kohdassa Oma tili.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Kaikki API-avaimet, jotka organisaation henkilöt ovat luoneet sen sovelluksille: haltija, sovellus, oikeudet ja viimeisin käyttö. Avain voi tehdä vain sen, mihin haltijalla on oikeus, ja lakkaa toimimasta tämän lähtiessä. Peru paljastuneet tai käyttämättömät avaimet. Käyttäjät luovat omansa kohdassa Oma tili.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Jokainen Cbox ID:n kautta käyttäjiä kirjauttava tai sen APIa kutsuva sovellus rekisteröidään tähän ja saa omat tunnukset. Rekisteröi yksi sovellusta ja ympäristöä kohti. Älä jaa tunnuksia niiden kesken, jotta yhden peruminen ei estä muiden toimintaa.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Kaikki selaimet ja laitteet, joilla olet kirjautuneena, valtuuttamasi sovellukset sekä viimeisimmät kirjautumiset ja turvallisuusmuutokset. Jos jokin on vierasta, kirjaa istunto ulos tai peru sovelluksen pääsy ja vaihda sitten salasanasi.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Kaikki organisaation muutokset: kuka teki mitä, mille kohteelle ja milloin. Merkinnät muodostavat hajautusketjun, joten muuttaminen tai poistaminen katkaisee ketjun ja paljastuu. Loki on tarkoituksella vain luettavissa ja toimii auditoinnin todisteena.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Kaikki Cbox ID:n ja muiden järjestelmien yhteydet yhdessä paikassa: SSO, ulkoiset kirjautumispalvelut, hakemisto- ja HR-synkronointi, lähtevä käyttäjien käyttöönotto, SAML-sovellukset, webhookit, hookit, lokivirrat ja putket. Kukin luettelokortti avaa oikean määrityssivun. Yhteydet näyttää nykyiset yhteydet tiloineen, virheelliset ensin.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Kaikki hallintakonsolissa valitun ympäristön organisaatiot jälleenmyyjien, niiden hallinnoimien organisaatioiden ja alayksiköiden puuna. Luo tai keskeytä organisaatio tai siirrä se toisen pääorganisaation alle.',
    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Kaikki tästä lähtien avaamasi sivut, kuten organisaatiot, käyttö ja organisaation tiedot, lukevat tämän ympäristön tietoja. Kummankaan ympäristön tietoja ei muuteta.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Kaikki henkilöt, joilla on identiteetti ympäristössä, organisaatioista riippumatta. Avaa henkilö nollataksesi salasanan tai kaksivaiheisen tunnistautumisen, päättääksesi istuntoja, poistaaksesi tilin käytöstä, muuttaaksesi organisaatioita ja rooleja tai poistaaksesi henkilön pysyvästi poistopyynnön perusteella.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Kaikki tässä tarkistuksessa kirjatut perumiset toteutetaan nyt. Tarkistamattomat kohteet käsitellään tarkistuskäytännön mukaan, jonka oletuksena on pääsyn peruminen. Tätä ei voi perua.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Kaikki salaisuudet, joilla sovellus voi tällä hetkellä tunnistautua. Kustakin tallennetaan vain hajautusarvo. Luettelo näyttää viimeiset neljä merkkiä, jotta tunnistat asennuksen käyttämän salaisuuden.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Kaikki sillä myönnetyt tunnisteet perutaan nyt, eikä sitä voi käyttää uusiin kirjautumisiin. Tunnisteet itse tarkistavat sovellukset hyväksyvät ne vanhenemiseen asti, kuitenkin enintään istunnon loppuun.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Kaikki kirjautumistavat tiloineen ja asetusten sijainteineen: salasana, pääsyavaimet, sähköpostilinkki, ulkoiset palvelut, Enterprise SSO ja toinen tekijä. Useimmista päättää ympäristö, SSO-yhteyksistä kukin organisaatio. Asennuksen rajoitukset näytetään niitä ohjaavien asetusten nimineen.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Kaikki asennuksen organisaatiot. Avaa organisaatio tuotteiden ja ympäristöjen hallintaan. Keskeyttäminen kirjaa jäsenet ulos ja pysäyttää tunnistautumisen kaikissa sen ympäristöissä.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Kaikki organisaation ylläpitäjät, heidän sisäiset roolinsa (Omistaja, Ylläpitäjä, Kehittäjä, Jäsen tai Katselija) ja käytettävissä olevat ympäristöt. Kutsu sähköpostitse ja anna vain työn edellyttämät ympäristöt.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Kaikki organisaatioon kirjautumaan pääsevät henkilöt sekä lähettämäsi hyväksymättömät kutsut. Kutsu sähköpostitse. Käyttäjät määrittävät kirjautumisensa itse, joten et käsittele heidän salasanojaan.',
