    'catalog_search_clients' => 'Hae OAuth-integraatioita',
    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Koodi voidaan varastaa SIM-kortin vaihdolla tai luvattomalla numeronsiirrolla, siepata puhelinverkossa tai syöttää aidolta näyttävälle väärennetylle kirjautumissivulle. Se on silti huomattavasti turvallisempi kuin pelkkä salasana. Ota se käyttöön henkilöille, jotka eivät voi käyttää tunnistautumissovellusta tai pääsyavainta.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Toiselta sivustolta ladattu logo paljasti kyseiselle sivustolle, kuka avasi kirjautumissivusi. Siksi palvelussa ylläpidetyt sivut näyttävät nyt vain tänne ladattuja kuvia. Lataa logo alla kohdassa :part2 tai poista se, niin tämä ilmoitus poistuu.',
    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 Rooli on tunnisteeseen lisättävä nimike. Sovelluksen määrittämiä rooleja voi täällä vain katsella; muut määrität itse. Jokaisella jäsenellä on lisäksi täsmälleen yksi :part2 :part3 :part4 (omistaja, ylläpitäjä, kehittäjä, jäsen tai katselija), joka määrää, mitä hän saa hallita tässä hallintakonsolissa.',
    '_part1_already_belongs_to_another_api_in_this_environme_bab95da8' => '”:part1” kuuluu jo tämän ympäristön toiselle API:lle. Tunnistepyynnössä käyttöoikeusalue nimetään vain avaimellaan, joten kukin avain voi kuulua vain yhdelle API:lle.',
    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => ':part1 kuuluvat API:lle, jota tämä sovellus ei saa käyttää. Ne jätetään pois kaikista tunnisteista. Poista ne kirjoitetuista käyttöoikeusalueista.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 voivat kirjautua salasanoilla tai tällä yhteydellä. Kertakirjautumisen vaatiminen estää kaikki muut kirjautumistavat, joten myöskään aiemmin myönnetyillä tunnisteilla ei voi ohittaa juuri määrittämääsi palveluntarjoajaa. Useimmat IdP:n yhdistävät yritykset haluavat tämän, mutta lue ensin, mitä asetus tekee.',
    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 ei sisällä vielä oikeuksia, joten :part2 :part3 on tyhjä. Roolin nimi on silti käytettävissä.:part4',
    '_part1_is_already_set_up_for_this_organization_change_i_dea89857' => ':part1 on jo määritetty tälle organisaatiolle. Muuta tunnistetietoja tai poista yhteys ensin.',
    '_part1_is_no_longer_offered_anyone_who_signed_in_with_i_b1a43020' => ':part1 ei ole enää tarjolla. Sillä kirjautuneet säilyttävät tilinsä ja voivat edelleen käyttää salasanaansa.',
    '_part1_is_off_on_every_sign_in_page_its_credentials_are_2dc58cfc' => ':part1 on poistettu käytöstä kaikilla kirjautumissivuilla. Tunnistetiedot säilytetään, joten voit ottaa sen uudelleen käyttöön.',
    '_part1_is_off_on_this_organization_s_sign_in_page_its_c_5a7d1345' => ':part1 on poistettu käytöstä tämän organisaation kirjautumissivulla. Tunnistetiedot säilytetään, joten voit ottaa sen uudelleen käyttöön.',
    '_part1_is_your_only_way_to_sign_in_set_a_password_or_ad_968a0fd3' => ':part1 on ainoa kirjautumistapasi. Aseta salasana tai lisää pääsyavain ennen yhteyden katkaisemista.',
    '_part1_is_your_organization_s_single_sign_on_it_is_how_a02887f1' => ':part1 on organisaatiosi kertakirjautumisyhteys. Organisaatiosi tunnistaa sinut sen avulla, joten yhteyttä ei voi katkaista täällä.',
    '_part1_its_team_is_administered_under_organization_team_6abad4af' => ':part1 Tiimiä hallitaan kohdassa Organisaatio › Tiimi organisaatioroolin avulla, ei täällä.',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 :part3 ei vielä määritä täällä mitään. Kun muutat jotakin alla, siitä tulee tämän organisaation oma sääntö.',
    '_part1_part2_up_to_date_part3_deprovisioned_part4_part5_5604a19e' => ':part1 :part2 ajan tasalla, :part3 poistettu käytöstä,:part4 :part5 ohitettu, ryhmiä :part6 :part7.',
    '_part1_part2_update_your_receiver_first_from_the_next_a_d1d60a6e' => ':part1 :part2 Päivitä ensin vastaanottaja: seuraavasta yrityksestä alkaen se hylkää kaikki toimitukset, joita se ei pysty todentamaan.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 hylkää kirjautumisen, jos tämä ei täsmää tarkasti. Arvo säilytetään tätä määritystä varten, joten voit liittää sen nyt kohteeseen :part2 ja tallentaa täällä sen jälkeen.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 – istunnot, pääsyavaimet ja toiset tunnistautumistekijät, identiteetintarjoajien profiilit, hakemistotiedot, myönnetyt tunnisteet, roolimääritykset ja auditointihistoria säilyvät ja ne voidaan ottaa uudelleen käyttöön.',
