    'welcome_back_part1_3c339e48' => 'Tervetuloa takaisin, :part1',
    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Mitä sovelluksen voidaan sallia tehdä tässä API:ssa. Vain kohteen :part1 omat sovellukset voivat saada nämä oikeudet.',
    'what_is_part1_00d3f3e7' => 'Mikä on :part1?',
    'what_you_are_administering_and_the_details_your_apps_ne_23bc71ef' => 'Hallitsemasi kohde ja sovellustesi integraatiota varten tarvitsemat tiedot. :part1',
    'withdraw_access_for_part1_10961483' => 'Peru sovelluksen :part1 käyttöoikeus',
    'withdraw_the_invitation_to_part1_13c82934' => 'Peru kohteelle :part1 lähetetty kutsu',
    'withdraw_the_invitation_to_part1_fafedcae' => 'Perutaanko kohteelle :part1 lähetetty kutsu?',
    'you_can_also_part1_part2_part3_53f32513' => 'Voit myös :part1 :part2 .:part3',
    'you_can_turn_it_off_again_on_part1_part2_sessions_that_89d71a9d' => 'Voit poistaa tämän jälleen käytöstä kohdassa :part1 :part2. Päättyneet istunnot pysyvät päättyneinä.',
    'you_hold_no_permissions_in_part1_so_a_key_would_identif_2c680207' => 'Sinulla ei ole oikeuksia kohteessa :part1, joten avain vain tunnistaisi sinut siellä.',
    'your_endpoint_verifies_the_part1_header_on_each_request_b7ca1bb8' => 'Päätepisteesi todentaa jokaisen pyynnön :part1-otsakkeen tällä salaisuudella.',
    'your_roles_using_permission' => 'Käytössä :count roolissasi|Käytössä :count roolissasi',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Kaikki organisaation tekemät määritykset ja jäljellä olevat tehtävät. Tarkistuslista näyttää todellisen tilanteen. Jokainen vaihe merkitään automaattisesti valmiiksi, kun se on tehty.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Kaikki käyttäjille näkyvät brändisi osat yhdellä sivulla: kirjautumissivun logo, selainkuvake, värit, kirjasintyyppi ja kulmat reaaliaikaisessa esikatselussa sekä tuotteen nimi, sähköpostin lähettäjä ja tervetuloviesti. Määritä asetukset kerran koko ympäristölle, jolloin kaikki organisaatiot perivät ne. Voit myös antaa organisaatiolle oman ulkoasun sen Visuaalinen ilme -välilehdellä.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Seuraavasta yrityksestä alkaen estot estävät kirjautumisen ja rekisteröitymisen tässä ympäristössä, ja lisätarkistukset edellyttävät lisävarmennusta. Virheellinen sääntö voi sulkea oikeita ihmisiä palvelun ulkopuolelle.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Myönnä sellainen ihmisille, jotka tukevat tai käyttävät sovelluksiasi. Sovelluksen oma rooli saavuttaa vain kyseisen sovelluksen tunnukset; kaikkien sovellusten rooli saavuttaa jokaisen niistä.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Ympäristön organisaatioiden, käyttäjien, kertakirjautumisyhteyksien, sovellusten ja käyttäjäsynkronointien määrät sekä linkit kunkin omalle sivulle. Alla olevilla pikavalinnoilla voit luoda tavallisimmat kohteet: organisaation, käyttäjän, kertakirjautumisyhteyden tai sovelluksen.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Kirjautuneiden henkilöiden määrä ja sovellustesi API-kutsujen määrä viimeisten 30 päivän ajalta. Yhteenveto auttaa arvioimaan kuormitusta ja havaitsemaan poikkeamia. Se ei ole lasku.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Kuinka usein tiedot haetaan ja mitkä HR-järjestelmän kentät kopioidaan kullekin henkilölle, esimerkiksi kustannuspaikka tai sijainti. Kenttien muuttamisen jälkeen seuraava synkronointi suoritetaan täydellisenä.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Näin auditointiloki viedään Cbox ID:stä: ajastettu vienti lähettää uudet merkinnät SIEM-järjestelmääsi tai arkistoosi viiden minuutin välein. Päivittäinen säilytystehtävä luo lokiin tarkistuspisteen poistamatta mitään. Täällä voit hakea henkilön auditointihistorian GDPR:n mukaista tietopyyntöä varten tai tarkistaa ympäristön hallintakonsolissa, että viennit suoritetaan.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Jos sovellus ilmoittaa myöhemmin toisen URL-osoitteen, hyväksyntä perutaan ja sinulta pyydetään uusi hyväksyntä. Salasanojen lähetysosoitetta ei saa muuttaa huomaamatta. Delegoitua kirjautumista käytetään siirtymävaiheessa. Kun vanhaa järjestelmää käyttää enää pieni joukko, poista delegoitu kirjautuminen käytöstä ja lähetä heille salasanan palautuslinkki.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Painike poistetaan ja tunnistetiedot poistetaan. Yhteydellä kirjautuneet säilyttävät tilinsä ja voivat edelleen käyttää salasanaansa. Jos haluat säilyttää tunnistetiedot, poista yhteys sen sijaan vain käytöstä.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Myös sen käyttöoikeusalueet poistetaan. Sovellukset säilyttävät ne kirjoitettuina käyttöoikeusalueina, jotka eivät enää anna pääsyä tähän API:in. Jo myönnetyt tunnisteet toimivat voimassaolonsa loppuun asti.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Ympäristön hallinta-API:n avaimet: hallitse yhden ympäristön organisaatioita, jäseniä, kutsuja, rooleja ja sovelluksia omasta taustajärjestelmästäsi. Jokaiselle avaimelle määritetään käyttöoikeusalueet erikseen.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Avaimet, jotka organisaation käyttäjät ovat luoneet sen sovelluksille, sekä kunkin avaimen oikeudet. Käyttäjät luovat omat avaimensa. Peru avain, jos se on vuotanut tai sitä ei enää käytetä.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Jätä kenttä tyhjäksi lähes kaikilla palveluntarjoajilla. Niiden ID-tunnisteet todennetaan discovery-asiakirjassa julkaistuilla allekirjoitusavaimilla (jwks_uri), myös avainten vaihtamisen jälkeen. Liitä palveluntarjoajan julkinen PEM-avain vain, jos se ei julkaise avaimia.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Salli kirjautuminen olemassa olevalla tilillä. Määritä palveluntarjoaja kerran ympäristölle, jolloin kaikki organisaatiot tarjoavat sen. Organisaatio voi sen sijaan käyttää omia tunnistetietojaan tai poistaa palveluntarjoajan käytöstä.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Anna sovellustesi käyttäjien yhdistää omat GitHub-, Google-, Slack- tai Salesforce-tilinsä, jotta sovellukset voivat kutsua näiden palvelujen API-rajapintoja käyttäjien puolesta. Tunnisteet tallennetaan salattuina, uusitaan täällä ja annetaan tilapäisesti vain valtuuttamiesi sovellusten käyttöön.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Antaa käyttäjiesi kirjautua olemassa olevalla Microsoft Entra ID-, Okta- tai Google Workspace -yritystilillään erillisen salasanan sijaan. Yhdistät identiteetintarjoajan kerran ja vahvistat sähköpostiverkkotunnuksesi. Sen jälkeen kaikki näitä verkkotunnuksia käyttävät ohjataan palveluntarjoajallesi kirjautumaan.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Kirjautuminen Entra ID:llä, Oktalla tai Google Workspacella on saatavilla Enterprise-tilauksessa. Ota yhteyttä asiakasvastaavaasi, jotta se voidaan ottaa käyttöön tälle organisaatiolle.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Organisaation IT-ylläpitäjälle annetut linkit, jotka ovat yhä voimassa. Linkin peruuttaminen estää sen käytön heti. Linkin avulla jo tehdyt määritykset säilyvät.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Hakee organisaatiota nimellä tai lyhyttunnisteella tai käyttäjää nimellä tai sähköpostiosoitteella asennuksen kaikista ympäristöistä, ei vain hallintakonsolissa avoinna olevasta ympäristöstä. Käytä hakua, kun joku tarvitsee apua etkä tiedä hänen ympäristöään.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Metatietoskeemat käyttävät JSON Scheman osajoukkoa: objektia, jonka ominaisuudet ovat merkkijonoja, lukuja, kokonaislukuja, totuusarvoja tai null-arvoja. Voit rajoittaa sallittuja arvoja, pituutta, arvoaluetta, mallia ja muotoa. Muutoksen tallentaminen luo uuden version. Jo tallennetut tapahtumat säilyttävät version, jota vasten ne tarkistettiin.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Lähettää jokaisen uuden auditointilokimerkinnän heti tietoturvatiimin työkaluihin, kuten SIEM-järjestelmään. Määritä tämä, jotta tutkinta voidaan aloittaa tiimin nykyisissä työkaluissa ilman erillistä vientipyyntöä. Toimitus tapahtuu vähintään kerran, joten satunnaisia kaksoiskappaleita voi esiintyä.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Useimpiin integraatioihin sopivat paremmin webhookit. Ne suoritetaan tapahtuman jälkeen eivätkä voi estää prosessin etenemistä. Käytä hookia vain, kun oman järjestelmäsi on voitava vaikuttaa kirjautumiseen tai tunnisteen myöntämiseen sen aikana.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Uutta salaisuutta ei myönnetä. Seuraavasta toimitusyrityksestä alkaen, myös uusintayrityksissä, käytetään toisen menetelmän otsakkeita. Vastaanottaja hylkää tällöin kaikki toimitukset, jos sitä ei ole päivitetty.',
    'nobody_is_on_this_organization_it_has_no_owner_so_nobod_0a51d66d' => 'Organisaatiossa ei ole jäseniä eikä omistajaa, joten kukaan ei voi kirjautua hallitsemaan sitä. Tämä viittaa selvitettävään käyttöönottovirheeseen, ei pelkästään tyhjään luetteloon.',
    'nothing_is_always_refused_and_nothing_skips_the_rules_d_6699d9d9' => 'Mitään merkintöjä ei aina estetä eikä vapauteta säännöistä. Estä hyökkäyksissä käytetty osoitealue tai vapauta toimistoverkkosi kirjautumistiheyttä rajoittavista säännöistä.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Näyttää Googlen, GitHubin, Applen ja muut palveluntarjoajat kirjautumissivun painikkeina henkilöille, jotka haluavat käyttää olemassa olevaa tiliä uuden salasanan sijaan. Määritä palveluntarjoaja kerran ympäristölle, niin kaikki organisaatiot tarjoavat sen. Organisaatio voi käyttää omia tunnistetietojaan tai poistaa palveluntarjoajan käytöstä. Annat tunnistetiedot, ja muut tiedot täytetään automaattisesti. Palveluntarjoajan ilmoittama sähköpostiosoite ei koskaan yksin riitä pääsyyn olemassa olevalle tilille täällä.',
    'on_for_this_percentage_of_everyone_the_rules_above_do_n_6ca1e886' => 'Käytössä tällä prosenttiosuudella henkilöistä, joihin yllä olevat säännöt eivät kohdistu. Käyttäjätunnisteen vakaa tiiviste valitsee samat henkilöt joka kerta; osuuden kasvattaminen vain lisää henkilöitä. Jätä tyhjäksi, jos et halua asteittaista käyttöönottoa.',
    'one_marked_event_siem_stream_test_sent_now_with_this_st_c0cf0c4a' => 'Yksi merkitty tapahtuma (siem.stream.test) lähetetään nyt tämän tietovirran asetuksilla ja tunnistetiedoilla ilman jonotusta tai uusintayrityksiä. Onnistuminen poistaa myös ”Toimia tarvitaan” -merkinnän.',
    'one_per_line_including_the_scheme_https_app_example_com_71de2531' => 'Yksi arvo riville protokolla mukaan lukien, esimerkiksi https://app.example.com. Jos jokin rivi on virheellinen, koko luettelo hylätään. Virheellisiä rivejä ei poisteta ilmoittamatta.',
    'one_type_per_resource_type_its_relation_s_below_it_a_re_18943de8' => 'Yksi `type` kutakin resurssityyppiä kohti ja sen `relation`-määritykset alle. Suhde määräytyy tuplen suoraan nimeämistä kohteista ([user, group#member]), toisesta suhteesta (owner), ylemmän tason kohteen suhteesta (viewer from parent) tai näiden yhdistelmästä operaattoreilla or, and tai but not.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Yksi tämän asennuksen organisaatio tiimeineen, projekteineen ja kaikkine projektien ympäristöineen. Organisaation poistaminen käytöstä kirjaa jäsenet ulos ja pysäyttää tunnistautumispalvelun kaikissa sen ympäristöissä.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Vain palveluntarjoajalle, joka ei julkaise allekirjoitusavaimia (jwks_uri) discovery-asiakirjassaan. Muussa tapauksessa avaimet haetaan sieltä myös niiden vaihtuessa. Anna julkinen PEM-avain. Se tallennetaan salattuna eikä sitä näytetä uudelleen. Jätä tyhjäksi, jos haluat säilyttää nykyisen avaimen.',
    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Vain valitun organisaation aktiiviset jäsenet voivat kirjautua tähän sovellukseen. Kaikkien muiden pääsy estetään, ja esto kirjataan auditointilokiin.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Organisaation tiedot kohdeympäristössä: jäsenet, SSO, verkkotunnukset, myönnetyt oikeudet ja viimeaikainen toiminta. Tällä sivulla voi muuttaa vain organisaation tilaa.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Tämän asennuksen kaikkien ympäristöjen organisaatiot, käyttäjät ja aktiiviset istunnot sekä organisaatiot, joissa on eniten jäseniä. Näkymä vain lukee tietoja eikä koskaan vaihda hallintakonsolissa valittua ympäristöä.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Valitse käyttämäsi ohjelmistokehys, niin sille luodaan sovellus, jossa on uudelleenohjaus paikalliselle kehityspalvelimellesi, kopioitavat ympäristömuuttujat ja kirjautumiskoodi. Sivu odottaa, kunnes joku todella kirjautuu. Alla ovat vaiheet tuotteen viimeistelyyn: visuaalinen ilme, organisaatiot, kertakirjautuminen, agentti, tiimin jäsen ja tuotantokäyttö. Vaiheet merkitään valmiiksi automaattisesti ympäristön todellisen tilan perusteella, ei käsin.',
    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Alustan ylläpitäjät hallitsevat tämän asennuksen kaikkia organisaatioita ja ympäristöjä niiden yläpuolelta. Lisää ylläpitäjäksi vain henkilö, joka vastaa itse asennuksen ylläpidosta, ja estä hänen pääsynsä heti, kun tehtävä ei enää kuulu hänelle.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Yhdistä identiteetintarjoaja SCIM-päätepisteeseemme, yhdistä Google Workspace tai Microsoft Entra tai liitä HR-järjestelmäsi: Workday, BambooHR, Rippling, HiBob tai Personio. Haemme henkilötiedot yhdistetyistä järjestelmistä ajastetusti.',
    'prove_which_email_domains_your_organization_owns_a_veri_a1717fad' => 'Vahvista organisaatiosi omistamat sähköpostiverkkotunnukset. Vahvistettu verkkotunnus voi ohjata kaikki sen osoitteita käyttävät henkilöt suoraan organisaation SSO-yhteyteen.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar arvioi jokaisen kirjautumisen ja rekisteröitymisen: varastetuilla tunnistetiedoilla tehdyt yritykset, bottimaisen nopeuden, maantieteellisesti mahdottomat siirtymät, uudet laitteet, anonymisoivat verkot ja kertakäyttöosoitteet sekä omat sääntösi ja sallinta- ja estolistasi. Jokainen päätös kirjataan. Kun otat toimeenpanon käyttöön, Radar estää pääsyn tai pyytää toista tunnistautumistekijää. Tarkista päätökset täällä ennen toimeenpanon käyttöönottoa ja silloin, kun joku ilmoittaa kirjautumisongelmasta.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar arvioi jokaisen kirjautumisen ja rekisteröitymisen: varastetuilla tunnistetiedoilla tehdyt yritykset, bottimaisen nopeuden, maantieteellisesti mahdottomat siirtymät, uudet laitteet, anonymisoivat verkot ja kertakäyttöosoitteet sekä omat sääntösi ja listasi. Päätösten perustelut kirjataan.',
    'refuse_passwords_found_in_known_data_breaches_checked_a_db4c6959' => 'Hylkää tunnetuissa tietovuodoissa esiintyneet salasanat. Tarkistus tehdään Have I Been Pwned -palvelun avulla lähettämättä koskaan salasanaa. Jos palveluun ei saada yhteyttä, rekisteröityminen sallitaan estämisen sijaan.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Rekisteröi sovellukset, jotka käyttävät tätä ympäristöä SAML-identiteetintarjoajanaan. Käyttäjät kirjautuvat täällä jo olevilla tileillään. Liitä kukin sovellus omaan organisaatioonsa, jotta vain sen jäsenet voivat kirjautua. Ilman organisaatiokytköstä sovellus on avoin kaikille ympäristön käyttäjille. Tämä on lähtevä suunta. Jos haluat sallia kirjautumisen muualla olevalla yritystilillä, käytä Tunnistautuminen-osion yritys-SSO:ta.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Pyynnöt näkyvät täällä automaattisesti, kun sovellus tai agentti tarvitsee hyväksyntäsi toimiakseen puolestasi. Ennen sitä sinun ei tarvitse tehdä mitään. Hylkää pyynnöt, joita et ole itse käynnistänyt.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Käyttäjän puolesta toimivien agenttien pyynnöt näkyvät täällä saapuessaan. Kukin käyttäjä hyväksyy omat pyyntönsä. Tällä sivulla voit hylätä väärinkäytöltä vaikuttavan pyynnön.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Tällä hetkellä henkilöt kirjautuvat täällä säilytettävillä tunnistetiedoilla. Yhdistä palveluntarjoajasi, niin he voivat käyttää olemassa olevaa yritystiliään. He menettävät pääsyn tänne heti, kun poistat tilin käytöstä palveluntarjoajalla.',
    'scopes_sign_out_uris_token_settings_and_the_roles_manif_c736e69a' => 'Käyttöoikeusalueet, uloskirjautumis-URI:t, tunnisteasetukset ja roolimanifestin URL-osoite kopioidaan sellaisinaan. Salaisuuksia, avaimia ja sovelluksen käyttäjiä ei kopioida. Ne kuuluvat ympäristöön, jossa ne luotiin.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Näe sovellus täsmälleen kuten sen käyttäjä: kirjaudut hänenä ilmoittamastasi syystä enintään tunniksi. Sovellukselle kerrotaan todellinen henkilöllisyytesi, eikä se saa keinoa jatkaa kirjautumista pysyvästi. Organisaation auditointilokiin kirjataan tekijä ja syy.',
    'send_this_single_use_link_to_whoever_configures_your_id_e8056999' => 'Lähetä tämä kertakäyttöinen linkki identiteetintarjoajasi asetuksista vastaavalle henkilölle. Se vanhenee pian ja toimii ilman tiliä. Kopioi se nyt, sillä se näytetään vain kerran.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Lähetä tämä kertakäyttöinen linkki organisaation identiteetintarjoajasta vastaavalle henkilölle, jos sitä ei jo lähetetty hänelle sähköpostitse. Se toimii ilman tiliä vanhenemiseen asti. Kopioi se nyt, sillä se näytetään vain kerran.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Tarjoaa ympäristön identiteettipäätepisteet omalla verkkotunnuksellasi, kuten login.example.com, meidän verkkotunnuksemme sijaan. Vahvistat omistuksen DNS-TXT-tietueella. Ota tämä käyttöön, jos käyttäjien tulee nähdä kirjautuessaan vain oma osoitteesi.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Aseta tämä roolin luottamuskäytännöksi (IAM › Roles › Trust relationships). Alusta voi ottaa roolin käyttöön vain esittämällä tämän tietovirran ulkoisen tunnisteen. Näin kukaan muu alustalla ei voi kohdistaa tietovirtaa rooliisi.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Kirjautumiset ja pyynnöt, jotka Cbox ID on arvioinut niin riskialttiiksi, että ne on merkitty tarkistettaviksi. Uusimmat näytetään ensin riskipisteineen ja perusteluineen. Tarkista näkymä, jos epäonnistuneet kirjautumiset lisääntyvät tai joku ilmoittaa kirjautumisesta, jota ei ole itse tehnyt.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Kirjautumiset, myönnetyt tunnisteet, uudet käyttäjät ja kaksivaiheisen tunnistautumisen käyttöönotot päiväkohtaisesti viimeisten 30 päivän ajalta, ellei asennukselle ole määritetty muuta ajanjaksoa. Sivu pysyy tyhjänä, kunnes ylläpitäjä määrittää analytiikkatietojen tallennuspaikan.',
    'snapshots_every_admin_support_role_each_role_held_acros_351f6f6d' => 'Tallentaa tilannekuvan kaikista ympäristön ylläpito- ja tukirooleista vahvistettaviksi tai peruttaviksi merkinnöiksi. Peruuttaminen poistaa roolin kaikissa organisaatioissa kerralla.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Ohjelmisto, joka toimii tässä ympäristössä hallinta-avaimella, kuten Claude Code, Cursor, sisäinen botti tai oma taustajärjestelmäsi. Kukin saa vain myöntämäsi käyttöoikeusalueet ja odottaa hyväksyntääsi valitsemissasi toiminnoissa.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Tiettyjä rooleja ei saa koskaan antaa samalle henkilölle. Maksun luovan henkilön ei tulisi myös hyväksyä sitä. Määritä nämä rooliparit täällä. Cbox ID estää uudet sääntöä rikkovat myönnöt ja näyttää, kenellä on jo molemmat roolit.',
    'splunk_elastic_graylog_cef_and_generic_json_are_http_co_8d405816' => 'Splunk, Elastic, Graylog, CEF ja Generic JSON ovat HTTP-vastaanottimia, joille annetaan URL-osoite. Datadog, Amazon S3 ja Google Cloud Storage käyttävät omia asetuksiaan.',
    'start_from_the_documents_in_folders_example_owners_edit_ca2a0af5' => 'Aloita kansioissa olevien asiakirjojen esimerkistä: omistajat, muokkaajat ja katselijat. Kansion käyttöoikeudet periytyvät kaikille sen sisältämille kohteille. Tuplet ja käyttöoikeustarkistukset tarvitsevat ensin skeeman.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Ominaisuuskytkimet, joita sovelluksesi kysyvät yhdelle henkilölle yhdessä organisaatiossa. Ota ominaisuus käyttöön nimetyille käyttäjille, organisaatioille tai osalle kaikista käyttäjistä. Kaikki sovellukset saavat saman vastauksen tunnisteessa tai API:n kautta.',
    'the_address_tokens_for_this_api_name_as_their_audience_cdea85aa' => 'Osoite, joka on tämän API:n tunnisteiden vastaanottajana ja jonka API tarkistaa. Sitä ei voi muuttaa myöhemmin, koska jo myönnetyt tunnisteet sisältävät tämän arvon.',
    'the_agent_is_refused_and_cannot_act_on_this_person_s_be_e1cd49d2' => 'Agentin pyyntö hylätään, eikä se voi toimia henkilön puolesta. Hylkäys kirjataan auditointilokiin, eikä sitä voi perua. Agentin on tehtävä uusi pyyntö.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Auditointitapahtumat, jotka sovelluksesi lähettää kustakin palvelemastaan organisaatiosta: kuka teki mitä tuotteessasi ja milloin. Ne tallennetaan organisaatiokohtaiseen tiivisteketjuun ja näytetään organisaation omille ylläpitäjille. Käytä tätä, kun organisaatio pyytää tilinsä auditointilokia. Määritä skeemat, jotta tapahtumat pysyvät yhdenmukaisina.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Sovelluksesi lähettämät auditointitapahtumat kaikista sen palvelemista organisaatioista, uusimmat ensin. Kunkin organisaation tapahtumat muodostavat oman tiivisteketjunsa.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'Auditointiloki sijaitsee täällä, mutta tietoturvatiimin työkalut muualla. Tietovirta lähettää jokaisen uuden merkinnän niihin heti, jotta tutkintaa ei tarvitse aloittaa CSV-vientipyynnöllä.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Painike poistuu organisaation kirjautumissivulta. Ympäristön oma palveluntarjoaja ei tule sen tilalle. Tunnistetiedot säilyvät, joten voit ottaa yhteyden uudelleen käyttöön.',
    'the_ceiling_on_this_app_s_access_narrowing_it_takes_eff_5f2865bc' => 'Sovelluksen käyttöoikeuksien yläraja. Rajoitus tulee voimaan seuraavasta tunnisteesta alkaen. Jos laite tai agentti pyytää poistamaasi käyttöoikeusaluetta, pyyntö hylätään sen sijaan, että oikeuksia vähennettäisiin ilmoittamatta.',
    'the_destination_refused_the_settings_a_missing_bucket_a_27207d67' => 'Kohde hylkäsi asetukset, esimerkiksi puuttuvan bucketin tai väärän alueen tai sijainnin vuoksi. Mitään ei toimiteta, ennen kuin asetukset on korjattu. Merkinnät jäävät odottamaan, eikä niitä hylätä.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Organisaation omistamat sähköpostiverkkotunnukset, kukin vahvistettuna DNS-TXT-tietueella. Vahvistamisen jälkeen voit ottaa pakotetun ohjauksen käyttöön: kaikki verkkotunnuksen osoitteita käyttävät ohjataan yrityksen SSO-yhteyteen salasanakirjautumisen sijaan. Vahvista siksi kaikki käyttäjiesi sähköpostiverkkotunnukset ennen kertakirjautumiseen siirtymistä.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Avaimet, joilla oma koodisi käyttää Cbox ID:tä, omalla välilehdellään kullekin tyypille. Salaisella hallinta-avaimella taustajärjestelmäsi hallitsee yhden ympäristön organisaatioita, jäseniä, kutsuja, rooleja ja sovelluksia. Organisaatioavain kutsuu organisaation API:a valmiilla roolilla. Julkaistavaa avainta käytetään selainsovelluksessa, ja se toimii vain sallimistasi alkuperistä. Salaiset avaimet ja organisaatioavaimet näytetään vain kerran. Kopioi ne luotaessa ja peru ne heti, jos ne vuotavat.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Vastakkainen suunta: Cbox ID siirtää käyttäjät yrityksesi muihin SaaS-tuotteisiin niiden SCIM-päätepisteiden kautta. Käyttöoikeuksien avaaminen ja sulkeminen hoidetaan yhdessä paikassa erillisten palveluntarjoajakohtaisten hallintapaneelien sijaan.',
    'the_name_of_your_organization_which_your_projects_envir_fde906b5' => 'Organisaatiosi nimi, jonka alle projektit, ympäristöt ja tiimi kuuluvat ja joka näkyy kaikkialla hallintakonsolissa. Organisaation poistaminen sulkee kaikki siihen kuuluvat kirjautumisympäristöt. Siksi poistamista pyydetään tuelta, eikä sitä tehdä painikkeella.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Jokaisessa kirjautumisessa sovellettavat salasanasäännöt, tilin lukitus sekä kaksivaiheisen tunnistautumisen ja kertakirjautumisen vaatimukset. Koko ympäristölle määritetään myös pääsyavainten ja kirjautumislinkkien saatavuus sekä istunnon kesto. Ympäristö määrittää perustason, jonka kaikki organisaatiot perivät. Organisaatio voi tiukentaa salasana- ja kaksivaiheisen tunnistautumisen sääntöjä mutta ei heikentää niitä.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Palvelusi, jotka vastaanottavat käyttöoikeustunnisteita, sekä kunkin omistamat käyttöoikeusalueet. Päätät itse, kenelle rekisteröidyn API:n käyttöoikeusalueet myönnetään. Kukaan ei saa pääsyä API:isi vain kirjoittamalla niitä sovelluksen asetuksiin.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Koko ympäristö tarjoaa palveluntarjoajan kaikilla kirjautumissivuilla. Valitse organisaatio, jos haluat määrittää sille oman palveluntarjoajan. Se korvaa ympäristön palveluntarjoajan kyseisen organisaation kirjautumissivulla.',
    'the_organization_s_own_keys_for_the_organization_api_li_86017b30' => 'Organisaation omat avaimet organisaation API:lle: luettele projektit ja ympäristöt, luo ympäristöjä sekä luettele ja kutsu tiimin jäseniä. Jokaisella avaimella on valmis rooli.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Henkilön istunnot ja tunnisteet perutaan. Pääsyavaimet, toiset tunnistautumistekijät, jäsenyydet, roolimyönnöt, API-tunnisteet, holvin salaisuudet, laitteet ja kaikki tallennetut henkilötietojen kopiot poistetaan. Tili säilytetään vain pseudonymisoituna, käytöstä poistettuna tietueena. Täältä henkilöitä synkronoiville sovelluksille lähetetään poistopyyntö. Auditointiloki säilyttää vain läpinäkymättömän tunnisteen, ei nimeä tai sähköpostiosoitetta.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Nämä hookit suoritetaan toiminnon aikana, ei sen jälkeen, ja niiden vastaus vaikuttaa lopputulokseen. Päätepisteesi voi lisätä tietoja tunnisteeseen tai estää kirjautumisen kokonaan. Ne vaikuttavat suoraan kirjautumisen kulkuun, joten hidas tai viallinen päätepiste näkyy heti kirjautuvalle henkilölle.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Henkilö menettää heti pääsyn tämän asennuksen kaikille alustasivuille. Olemassa olevat istunnot lakkaavat toimimasta seuraavalla pyynnöllä. Voit ottaa henkilön uudelleen käyttöön täällä.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Tätä ei voi perua. Tunnistetiedot, jäsenyydet ja henkilötiedot poistetaan, ja tili pseudonymisoidaan. Jos henkilö on organisaation ainoa omistaja, siirrä omistus ensin.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Asennuksessa ei ole Turnstile-avaimia (CBOX_ID_TURNSTILE_SITE_KEY), joten Turnstile-tarkistusta ei voi ottaa käyttöön. Riskialttiiksi merkityssä rekisteröitymisessä vahvistetaan sen sijaan sähköpostiosoite.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Tämä päätepiste kuuluu ympäristölle ja suoritetaan sen jokaiselle organisaatiolle. Se näytetään täällä, koska sitä käytetään kirjautumisissasi. Sen hallinnasta vastaa alustan ylläpitäjä.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Tämä ympäristö tarjoaa REST-API:n rinnalla MCP-palvelimen. Yhdistä agentti siihen hallinta-avaimella. Se voi suorittaa vain avaimen käyttöoikeusalueiden sallimat toiminnot samoilla tarkistuksilla, hyväksynnöillä ja auditointilokilla kuin hallintakonsoli.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Tämä ympäristö tarjoaa REST-API:n rinnalla MCP-palvelimen, joka on tekoälyavustajien työkalukutsujen vakiorajapinta. Syötä osoite ja hallinta-avain Claude Codeen, Cursoriin tai muuhun MCP-asiakkaaseen. Agentti voi suorittaa vain avaimen käyttöoikeusalueiden sallimat toiminnot samoilla tarkistuksilla ja auditointilokilla kuin hallintakonsoli.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Käyttäjä ei voi enää kirjautua mihinkään tämän ympäristön sovellukseen. Olemassa olevat istunnot lakkaavat toimimasta seuraavalla pyynnöllä. Tiedot säilyvät, ja voit ottaa käyttäjän uudelleen käyttöön milloin tahansa.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Tämä käyttäjä omistaa organisaation tai hallinnoi sitä. Tällaisena käyttäjänä ei voi kirjautua tukitarkoituksessa, koska se voisi antaa toiselle henkilölle pysyvän hallintaoikeuden organisaatioon.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Tällä hetkellä henkilöitä lisätään ja poistetaan täällä käsin. Yhdistä yrityksen jo käyttämä hakemisto, niin molemmat hoituvat automaattisesti, myös helposti unohtuvat poistot.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Ennen API:n rekisteröintiä käyttöoikeusalue on vain tekstiä sovelluksen asetuksissa. Jokainen, joka voi muokata sovellusta, voi lisätä sille minkä tahansa käyttöoikeusalueen. Rekisteröi sovellustesi kutsumat API:t, jotta niiden käyttöoikeusalueilla on omistaja.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Vahvistetut verkkotunnukset ohjaavat käyttäjät omalle identiteetintarjoajallesi. Toiminto kuuluu Enterprise-tilaukseen. Ota yhteyttä asiakasvastaavaasi, jotta se voidaan ottaa käyttöön tälle organisaatiolle.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Kun vahvistat omistamasi verkkotunnuksen, esimerkiksi acme.com, Cbox ID tunnistaa käyttäjäsi sähköpostiosoitteen perusteella ja ohjaa heidät suoraan palveluntarjoajallesi. Näin kenenkään ei tarvitse valita oikeaa kirjautumispainiketta.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhookit, uloskirjautumisilmoitukset yhdistetyille sovelluksille, roolipäivitysten haku ja jonotetut sähköpostit käsitellään taustalla jonotyöntekijöillä ilman, että henkilön tarvitsee odottaa. Jos yhtään jonotyöntekijää ei ole käynnissä, mitään näistä ei käsitellä, vaikka hallintakonsoli muuten näyttää normaalilta. Tältä sivulta näet ongelman.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Toiminnot, joihin tämän ympäristön agentit odottavat hyväksyntää. Jos avain edellyttää hyväksyntää, agentti pysähtyy ja kysyy avaimen luoneelta henkilöltä. Hän voi vastata puhelimellaan tai täällä. Ympäristön ylläpitäjä voi hylätä epäilyttävän pyynnön. Alla ovat sovellusten pyynnöt toimia käyttäjän puolesta; jokainen käyttäjä hyväksyy ne itse.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Mitä sovelluksen voidaan sallia tehdä tässä API:ssa. Omat sovelluksesi voivat saada kaikki käyttöoikeusalueet. Organisaation rekisteröimät sovellukset voivat saada vain organisaatioille merkityt alueet.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Toiminnot, joihin tämän ympäristön ohjelmistot odottavat hyväksyntää. Hyväksyntää vaativaa avainta käyttävä agentti pysähtyy ja kysyy avaimen luoneelta henkilöltä. Vastaa täällä tai puhelimellasi.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'Avain, jota koodisi kysyy ja jonka feature_flags-väite sisältää. Pieniä kirjaimia ja numeroita, joiden välissä voi olla - _ tai . Avainta ei voi muuttaa myöhemmin.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Kun sovellus tai tekoälyagentti tarvitsee hyväksyntäsi toimiakseen puolestasi, se ei aina voi kysyä sitä edessäsi olevalla näytöllä. Siksi pyyntö näkyy täällä. Hyväksy vain itse käynnistämäsi pyynnöt ja tarkista, että näytetty koodi vastaa pyytävän laitteen koodia.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Kun KAIKKI ehdot täyttyvät, Radar suorittaa tämän säännön toiminnon eikä tarkista myöhempiä sääntöjä. Nämä säännöt tarkistetaan sallinta- ja estolistojen jälkeen ja ennen valmiita sääntöjä.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Osoite, johon Cbox ID ohjaa henkilöt sovelluksesta uloskirjautumisen jälkeen. Sovelluksen pyytämän URI:n on oltava tässä täsmälleen samana, myös lopun vinoviiva mukaan lukien. Muuten henkilö jää Cbox ID:n omalle uloskirjautumissivulle. Jätä tyhjäksi, jos sovellus ei koskaan pyydä paluuohjausta.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Missä olet kirjautuneena, mikä voi toimia puolestasi ja mitä tililläsi on tapahtunut. Jos näet jotakin tuntematonta, kirjaa kyseinen istunto ulos ja vaihda salasanasi.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Kun siirryt toisesta järjestelmästä, sovellus voi ilmoittaa vanhan kirjautumispäätepisteensä manifestissa roolien yhteydessä. Se näytetään täällä hyväksyttäväksi ennen käyttöönottoa.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Kun siirryt toisesta järjestelmästä, sovellus voi pyytää tarkistamaan niiden henkilöiden sähköpostiosoitteen ja salasanan vanhasta kirjautumispäätepisteestä, joita ei vielä ole Cbox ID:ssä. Testaa päätepiste ennen hyväksymistä. Sen hyväksymä henkilö luodaan tänne, eikä häntä enää ohjata sinne. Jos päätepiste ei toimi, vielä siirtymättömät henkilöt eivät voi kirjautua.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Ilman rooleja kaikki kirjautuvat saavat sovelluksen tavalliselle käyttäjälle antamat oikeudet. Rooleilla määrität kerran esimerkiksi muokkaajat ja tukihenkilöt, ja kaikki yhdistetyt sovellukset voivat noudattaa samaa jakoa.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Luo sääntö, joka sallii pääsyn, vaatii lisätodennuksen tai estää pääsyn käyttäjistä tietämiesi asioiden perusteella. Vaadi esimerkiksi lisätodennus kirjautumisissa toimintamaidesi ulkopuolelta tai vapauta toimistoverkkosi kirjautumistiheyden rajoituksista.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Toimit tämän henkilön nimissä, hänen istunnossaan ja hänen käyttöoikeuksillaan. Aika on rajattu 30 minuuttiin, ja käyttö on vain luku -tilassa siellä, missä hallintakonsoli voi sen varmistaa. Jokainen pyyntö kirjataan nimellesi.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Menetät pääsyn heti. Omistajana voit poistua organisaatiosta vasta, kun joku muu omistaa sen. Siirrä ensin omistus tai poista organisaatio Asetukset-kohdassa.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Sovelluksesi oma pääsynhallintamalli: resurssityypit kuten asiakirjat ja kansiot, suhteet kuten omistaja, muokkaaja ja katselija sekä niiden periytyminen. Kansion katselija voi esimerkiksi lukea kaikki sen asiakirjat. Sovellus tallentaa henkilöiden suhteet resursseihin ja kysyy jokaisella pyynnöllä: ”saako tämä käyttäjä muokata tätä asiakirjaa?”. Skeema määrää vastauksen.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Sovelluksen oma käyttöoikeusmalli: resurssityypit, niiden suhteet ja suhteiden periytyminen. Sovellus tallentaa monikkoja — kenellä on mikäkin suhde mihinkin resurssiin — ja tarkistaa oikeudet jokaisella pyynnöllä.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Sovellus lähettää nämä tapahtumat yhdellä kutsulla tapahtumaerää kohti. Jokainen tapahtuma ilmoittaa organisaation, jossa se tapahtui. Ne näkyvät täällä ja kyseisen organisaation ylläpitäjille heti saavuttuaan.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Ympäristön oletusilme: ylläpidetyn kirjautumissivun ulkoasu, logo ja sivustokuvake sekä käyttäjille näkyvä nimi ja lähettäjä. Kaikki organisaatiot perivät sen, elleivät määritä omaansa.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Identiteetintarjoaja luo, päivittää ja poistaa henkilöitä käytöstä täällä automaattisesti SCIM-standardin kautta. Kun henkilö aloittaa tai lähtee HR-järjestelmässä, muutos välittyy sovelluksiin sekunneissa ilman tukipyyntöjä tai jäljelle jääviä tilejä — juuri lähtötilanteessa tämä on tärkeää.',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Omat kirjautumistapasi ja aktiiviset istuntosi. Pääsyavain tarjoaa vahvimman suojan ja on nopein käyttää: laitteesi avaa sen sormenjäljellä tai kasvojentunnistuksella, eikä jäljelle jää salasanaa, jonka voisi varastaa tietojenkalastelulla.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Vastaanottaja säilyttää saman salaisuuden. 64 merkin heksadesimaalinen salaisuus muunnetaan muotoon whsec_ ja merkkijonon base64-koodaus — "whsec_" + base64(secret). Jos salaisuus alkaa jo etuliitteellä whsec_, sitä käytetään sellaisenaan.',
    '_groups_part1_39d243e0' => '{
  "groups": [":part1"]
}',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => 'Suositeltavia tehtäviä: :part1, suunnilleen tässä järjestyksessä. Jokainen tehtävä merkitään automaattisesti valmiiksi, kun se on todella tehty. Mitään ei tarvitse merkitä valmiiksi käsin.',
    '_sub_the_person_s_id_org_the_organization_they_are_acti_2e2ddc7f' => '{
  "sub": "henkilön tunniste",
  "org": "organisaatio, jonka puolesta henkilö toimii",
  "roles": [":part1"],
  "permissions": [:part2]
}',
    'an_api_key_organization_settings_api_keys_not_an_applic_916c023d' => 'API-avain (Organisaatioasetukset › API-avaimet), ei sovellusavain. Tallennetaan salattuna, eikä sitä näytetä enää koskaan.:part1',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Kuinka ihmiset kirjautuvat sisään :part1-palveluun. Nämä alkavat ympäristösi oletusarvoina; kaikki mitä muutat täällä voi vain tehdä niistä tiukempia.',
    'its_members_are_signed_out_and_all_part1_it_owns_stop_s_80b419eb' => 'Sen jäsenet on kirjattu ulos ja kaikki sen omistamat :part1 lopettavat todennuksen näyttämisen seuraavassa pyynnöstä. Voit aktivoida sen uudelleen täällä.',
    'its_part1_are_signed_out_and_all_part2_it_owns_stop_ser_c1a0c179' => 'Sen :part1 on kirjautunut ulos ja kaikki sen omistamat :part2 lopettavat todennuksen näyttämisen seuraavassa pyynnöstä. Voit aktivoida sen uudelleen täällä.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Organisaation :part1 eivät voi enää kirjautua tähän organisaatioon, eivätkä siihen tukeutuvat sovellukset voi enää todentaa heitä. Aliorganisaatioita ei poisteta käytöstä samalla. Voit ottaa organisaation uudelleen käyttöön täällä.',
    'minutes_at_most_part1_empty_uses_the_deployment_s_part2_2c261db9' => 'Minuutit, enintään :part1. Tyhjä käyttää käyttöönoton :part2. Sen lyhentäminen lopettaa myös jo käynnissä olevat pidemmät istunnot.',
    'only_if_your_app_needs_more_from_part1_than_sign_in_doe_fc539001' => 'Vain jos sovelluksesi tarvitsee enemmän :part1:stä kuin sisäänkirjautuminen – välilyönnillä erotettuna. Omat kirjautumisalueet pyydetään aina.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Liitä ämpäriin palvelutilin koko JSON-avaintiedosto, jolle on myönnetty roles/storage.objectCreator. Tallennetaan salattuna, eikä sitä näytetä enää koskaan.:part1',
    'sandbox_environments_allow_localhost_urls_and_never_sen_299fef2d' => 'Sandbox-ympäristöt sallivat paikalliset URL-osoitteet eivätkä koskaan lähetä oikeaa sähköpostia. :part1 jäljellä tämän projektin suunnitelmassa.',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Kirjaudu johonkin sovelluksestasi nimellä :part1 nähdäksesi, mitä he näkevät. Sovellukselle kerrotaan, että se olet sinä, ja organisaation tarkastusloki kirjaa kuka, milloin ja miksi.',
    'the_app_whose_declared_roles_and_permissions_tokens_for_f9092feb' => 'Sovellus, jonka julistetut roolit ja luvat tuovat tälle API-kannalle. Vain :part1:n omistamat sovellukset voidaan valita.',
    'what_part1_s_sign_in_page_offers_providers_from_the_env_efc01f8e' => 'Mitä :part1:n kirjautumissivu tarjoaa. Ympäristön toimittajat ovat periytyneitä; tämä organisaatio voi kytkeä yhden pois päältä tai perustaa oman tilalleen.',
    'when_an_agent_s_key_needs_approval_for_an_action_the_re_56c5e366' => 'Kun agentin avain tarvitsee hyväksyntää toiminnalle, pyyntö tulee esiin tässä ja avaimen luoneen henkilön puhelimessa. Se odottaa jopa :part1:een asti.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Mikä tarkoittaa, että :part1 tarjoaa salasanan lisäksi, ja kuinka kauan sisäänkirjautuminen kestää. Nämä ovat samat jokaiselle organisaatiolle siinä.',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Väitteen :part2 merkitys on eri: se kertoo, mitä :part3 :part4 sai pyytää, ei sitä, mitä :part5 saa tehdä.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Niitä ei käytetä tähän konsoliin kirjautumiseen. Ylläpitäjät kirjautuvat Cbox ID:n kautta osoitteessa :part2 käyttäen sen kirjautumistapoja.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Valitse käyttöoikeusalue :part2 :part3 sovellusta rekisteröidessäsi. ID-tunniste sisältää silloin samat roolien nimet väitteessä :part4, jota Kubernetes, Grafana ja Vault käyttävät. Muita määrityksiä ei tarvitse luoda.',
    '_part1_you_are_impersonating_part2_part3_for_support_ev_aaad4d39' => ':part1 Toimit tukitarkoituksessa käyttäjänä :part2 :part3. Kaikki toimintasi kirjataan lokiin. :part4 :part5 :part6',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Hallinta-avain toimii vain omassa ympäristössään. Vie sovelluksen määritysmalli (GET /apps/{id}/blueprint) ja rekisteröi se toisen ympäristön avaimella (POST /apps käyttäen kenttää `blueprint`).',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Hallinta-avain yhdelle agentille. Se sallii vain käyttöoikeusalueiden mukaiset toiminnot. Valitsemasi toiminnot odottavat hyväksyntääsi puhelimessa tai kohdassa :part1.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'Sivu osoitteessa :part1. Jätä kenttä tyhjäksi, jos haluat avata konsolin ja nimetä kutsussa kohteen :part2.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => ':part1 on yhden tuotteen identiteetintarjoaja. Se sisältää erilliset :part2 :part3 eli tuotanto- ja testiympäristön, joilla kummallakin on omat käyttäjänsä, avaimensa ja kirjautumisensa. Sillä on oma laskutettava tilaus.',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'Oikeus määrittää, mitä :part1 saa tehdä kirjautumisen jälkeen. Se, mitä :part2 saa pyytää, määritetään käyttöoikeusalueella rekisteröinnin yhteydessä kohdassa :part3 :part4.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'Organisaation avain antaa pääsyn organisaatioon eli projekteihin, ympäristöihin, tiimiin ja avaimiin, mutta ei ympäristön sisäiseen sisältöön. Luo avain alustan juuritasolla kohdassa :part1 :part2 :part3.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Tämän sovelluksen käyttöoikeustunnisteiden vastaanottajaksi on määritetty :part1 :part2. Kyseisen API:n tulee hyväksyä tunniste vain, jos se on nimetty tunnisteen vastaanottajaksi.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Tämän sovelluksen käyttöoikeustunnisteiden vastaanottajaksi on määritetty ympäristön myöntäjä, :part1 :part2. Tämä muuttuu, kun sovellus saa käyttöoikeusalueen jostakin rekisteröidystä API:stasi.',
    'add_a_txt_record_at_part1_part2_with_the_value_below_th_455edc17' => 'Lisää TXT-tietue kohtaan :part1 :part2 käyttäen alla olevaa arvoa ja napsauta sitten Vahvista. DNS-muutosten voimaantulo voi kestää muutaman minuutin.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'Sovellus rekisteröi luettelonsa SDK:n kautta. :part1 :part2 Voit luoda roolin nyt ja valita sen käyttöoikeudet, kun avaimet ovat saapuneet.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Sovellukset, jotka luottavat tähän ympäristöön SAML-identiteetintarjoajana. Jos haluat sallia kirjautumisen muualla jo olemassa olevalla tilillä, käytä kohtaa :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Hyväksynnät koskevat hallinta-API:n toimintoja. Näitä käyttöoikeusalueita käyttävät päätepisteet eivät vielä ole toimintoja, joten ne suoritetaan ilman hyväksyntäpyyntöä: :part1 :part2.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Sovellukset ohjaavat käyttäjiä rekisteröitymään parametrilla :part1 ja pyytävät kirjautunutta henkilöä luomaan organisaation parametrilla :part2. Molemmat ovat käytettävissä vain, kun tämä asetus on käytössä.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'Kysely tehdään täsmälleen samalla tavalla kuin sovelluksesi tekee sen (:part1), mukaan lukien kaikki skeeman määrittämät periytymissäännöt.',
    'auth_settings_differ' => ':count asetus eroaa ympäristösi asetuksista.|:count asetusta eroaa ympäristösi asetuksista.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Yhdistä kerran alustan juuritasolla sen sijaan, että yhdistäisit jokaiseen ympäristöön erikseen. Sinuna kirjautunut työkalu saa pääsyn organisaatioosi, kaikkiin sen hallinnoimiisi ympäristöihin ja omaan tiliisi. Ympäristötyökalu käyttää argumenttia :part1 :part2 ja REST-API otsaketta :part3 toiminnon kohteen määrittämiseen. Työkalu voi tehdä vain sen, mihin sinulla on oikeus ja minkä sallit. Jokainen kriittinen toiminto odottaa hyväksyntääsi omalla laitteellasi.',
    'each_new_account_creates_its_own_organization_and_owns_3528fda3' => 'Jokainen uusi tili luo oman organisaationsa ja omistaa sen. Sovellukset voivat myös pyytää kirjautunutta henkilöä luomaan organisaation käyttämällä :part1 :part2.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Henkilölle määritetään kussakin organisaatiossa yksi hallintarooli (”:part1”), joka määrää, mitä hän saa hallita siellä. Lisäksi hänelle voidaan antaa haluttu määrä sovellusten käyttöoikeuksia määrittäviä rooleja (”:part2”).',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Ympäristö ”:part1” on luotu. Lisää :part2 ympäristön verkkotunnusasetuksissa ja vahvista se DNS:n avulla. Vahvistamaton verkkotunnus ei voi toimia ympäristön myöntäjänä.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'Ympäristöt kuuluvat projektiin ja projekti kohteeseen :part1 :part2 :part3. Aloita sieltä nähdäksesi organisaation kaikki resurssit. Kaksi tietuetyyppiä ei koskaan kuulu organisaatioon: :part4 on ympäristö, jossa tämä asennus itse toimii ja jossa alustan ylläpitäjien sekä organisaatioiden jäsenten tilit sijaitsevat. :part5 :part6-ympäristöllä ei ole projektia, joten sitä ei laskuteta eikä mikään organisaatio pääse siihen. Kumpikaan ei ole tällä sivulla korjattava virhe, eikä niiden kohdistusta voi muuttaa täällä.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Kaikki kirjautumistavat kohteeseen :part1, niiden käytössäolo ja paikka, jossa niitä muutetaan. Organisaatiot voivat asettaa tiukempia vaatimuksia: :part2 :part3.',
    'every_organization_environment_and_operator_on_part1_a__f425b7e6' => 'Kaikki organisaatiot, ympäristöt ja alustan ylläpitäjät kohteessa :part1. Täällä tehty käytöstäpoisto, uusi ympäristö tai ylläpitäjän muutos vaikuttaa koko alustaan.',
    'feature_flag_part1_created_it_is_off_for_everyone_until_32603be3' => 'Ominaisuuslippu ”:part1” on luotu. Se on pois käytöstä kaikilta, kunnes jokin alla olevista säännöistä tai oletusasetus ottaa sen käyttöön.',
    'framework_3cf574caed49' => 'Käyttöoikeusalueet :value1 kuuluvat rekisteröityyn API:in, jonka käyttöoikeusalueita tämä asiakas ei saa käyttää. Organisaation omistama asiakas voi käyttää oman organisaationsa API:en käyttöoikeusalueita sekä ympäristön API:en käyttöoikeusalueita, joiden pyytäminen on sallittu asiakasorganisaatioille.',
    'framework_43fd205dea6a' => 'Käyttöoikeusalue [:key] kuuluu jo toiselle API:lle tässä ympäristössä. Käyttöoikeusalueiden avaimet ovat ympäristökohtaisesti yksilöllisiä, koska tunnistepyyntö nimeää käyttöoikeusalueen vain sen avaimella.',
    'framework_47867973811e' => 'Hakemistosynkronointi palvelun :provider kanssa epäonnistui: :request saavutti pyyntömäärärajan (HTTP :status) :attempt yrityksen jälkeen.',
    'framework_5eb368b0fb37' => 'Workday: Raportin URL-osoitteen on oltava raportin verkkopalveluosoite: …/ccx/service/customreport2/{tenant}/{owner}/{report}.',
    'framework_632573ec7b49' => 'Sovelluksella [:clientId] on oltava sama omistaja kuin API:lla, jonka käyttöoikeuksia se valvoo. Yhdistäminen lisäisi yhden omistajan roolit ja käyttöoikeudet toisen omistajan tokeneihin.',
    'framework_87da9891b0ad' => 'Hakemistosynkronointi palvelun :provider kanssa epäonnistui: :request ei ollut käytettävissä (HTTP :status) :attempt yrityksen jälkeen.',
    'framework_98eb4683e38b' => 'Hakemistosynkronointi palvelun :provider kanssa epäonnistui: :request epäonnistui (HTTP :status): ei löytynyt. Tarkista tili, aliverkkotunnus tai raportin osoite.',
    'framework_a934fd6a0c26' => '[:origin] käyttää http-yhteyttä, joten avain ja kaikki sillä tehdyt toiminnot siirtyisivät verkossa salaamattomina. Käytä https-yhteyttä tai kehityksen aikana loopback-osoitetta, kuten http://localhost:3000.',
    'framework_b63785ee57fb' => 'Hakemistosynkronointi palvelun :provider kanssa epäonnistui: :request epäonnistui (HTTP :status): tunnistetiedoilla ei ole oikeutta lukea työntekijätietoja.',
    'framework_e5ca82ab9dff' => 'Hakemistosynkronointi palvelun :provider kanssa epäonnistui: :request epäonnistui (HTTP :status): tunnistetiedot hylättiin.',
    'framework_fc1964a8e8c4' => 'Tämä on asiakkaan [:clientId] viimeinen voimassa oleva salaisuus. Korvaa se kierrättämällä salaisuus. Jos peruutat sen, asiakas ei voi enää tunnistautua.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Jos päätepiste on :part1, käyttäjät, joita ei ole vielä siirretty, eivät voi kirjautua. Jo siirrettyihin käyttäjiin tämä ei vaikuta.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'Siinä järjestyksessä kuin ne näytetään käyttäjille. Ympäristön palveluntarjoajan poistaminen käytöstä täällä poistaa vain painikkeen tältä sivulta. Sillä voi yhä kirjautua muualla. Jos identiteetintarjoajasi tulee olla ainoa kirjautumistapa, vaadi SSO kohdassa :part1 :part2.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Avaimet alkavat tällä etuliitteellä, joten lokista löytynyt avain voidaan yhdistää tähän sovellukseen: :part1 :part2. 2–16 pientä kirjainta tai numeroa, joiden jälkeen tulee :part3 tai :part4 :part5. Etuliitteen on oltava yksilöllinen tässä ympäristössä. Etuliitteen asettaminen ottaa avaimet käyttöön. Sen poistaminen estää uusien avainten luomisen; aiemmin luodut toimivat, kunnes ne perutaan.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Luettele ominaisuusliput kohdennussääntöineen ja arvioi jokainen lippu organisaation käyttäjälle. Tätä sovelluksen taustajärjestelmä pyytää, kun sillä ei ole tunnistetta.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Luettele henkilöitä synkronoivat hakemistot (SCIM, Google Workspace, Microsoft Entra), niiden ryhmät ja synkronointivirheet. Bearer-tunnisteita tai palveluntarjoajien tunnistetietoja ei koskaan palauteta.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Luettele organisaatioiden kirjautumiseen käyttämät SAML- ja OIDC-yhteydet sekä käyttäjiä niihin ohjaavat sähköpostiverkkotunnukset. Varmenteita, asiakassalaisuuksia tai allekirjoitusavaimia ei koskaan palauteta.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Luettele ulkopuoliset palveluntarjoajat, joihin käyttäjät voivat yhdistää tilinsä, niiden tunnisteita tilapäisesti käyttävät valtuutetut sovellukset sekä yhteyden muodostaneet henkilöt. Asiakassalaisuuksia tai tunnisteita ei koskaan palauteta.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Luo ja peru kertakäyttöisiä ylläpitäjäportaalin linkkejä. Linkillä organisaation IT-ylläpitäjä voi määrittää SSO:n, verkkotunnukset tai hakemistosynkronoinnin ilman tiliä. Uusi linkki näytetään vain kerran.',
    'no_roles_to_map_onto_yet_define_one_under_part1_part2_o_9b9aba76' => 'Kohdistettavia rooleja ei vielä ole. Määritä rooli kohdassa :part1 :part2 tai anna sovelluksen ilmoittaa omat roolinsa.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'Kukaan tässä organisaatiossa ei ole luonut avainta sen sovelluksille. Käyttäjät luovat omat avaimensa kohdassa Oma tili sovellukselle, jonka asetuksissa jäsenten API-avaimet on otettu käyttöön: :part1.',
    'nobody_is_signed_in_to_an_app_as_one_of_its_people_star_a41ae388' => 'Kukaan ei ole kirjautunut sovellukseen toisen käyttäjänä. Aloita tällainen istunto henkilön sivulta kohdasta :part1 :part2.',
    'only_the_console_can_give_an_app_part1_not_a_management_e9037160' => 'Vain konsoli voi myöntää sovellukselle oikeuden :part1. Hallinta-avain tai puolestasi toimiva agentti ei voi tehdä sitä. Myönnä oikeus konsolissa sovelluksen Scopet-sivulla.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Tarjolla on vain toimintoja, jotka saat itse tehdä kohteessa :part1. Jos menetät käyttöoikeuden myöhemmin, myös avain menettää sen.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Lisää henkilölle käytössä olevien ominaisuuslippujen avaimet kirjautumisorganisaatiossa käyttöoikeustunnisteeseen, ID-tunnisteeseen ja UserInfo-vastaukseen väitteenä `feature_flags`.',
    'puts_everything_userinfo_answers_for_the_app_s_scopes_e_db47369d' => 'Lisää ID-tunnisteeseen kaiken, minkä UserInfo palauttaa sovelluksen oikeusalueille (sähköposti, nimi, roolit, käyttöoikeudet, organisaatiot), jotta sovellus voi jättää UserInfo-kutsun pois kirjautumisessa. Vain sovellukselle, joka lähettää `id_token_hint`-arvon uloskirjautumisessa POST-pyynnöllä tai ei lainkaan: URL-osoitteessa oleva tunniste tallentuu käyttölokeihin.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Lisää henkilön ROOLIT ID-tunnisteeseen nimellä `groups`, jota Kubernetes, Grafana, Vault ja monet vanhemmat SaaS-sovellukset käyttävät. Tässä hallintakonsolissa ei ole ryhmä-nimistä kohdetta. Luo rooli sovelluksen odottamalla nimellä, niin se lisätään tunnisteeseen.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Lue Radarin tila, valmiit ja omat säännöt, sallinta- ja estolistat sekä päätösnäkymä: miksi kirjautuminen tai rekisteröityminen sallittiin, vaati lisätodennuksen tai estettiin. Päätösten IP- tai sähköpostiosoitteita ei koskaan palauteta.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Lue sovelluksesi lähettämät auditointitapahtumat ja niistä tehdyt viennit, todenna organisaation tapahtumaketju sekä lue tapahtumiin sovellettavat skeemat ja säilytyssäännöt.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Lue valtuutusskeema ja sen tuplet sekä suorita käyttöoikeustarkistuksia ja luettelokyselyjä, kuten ”saako tämä käyttäjä muokata tätä asiakirjaa?” tai ”mitkä asiakirjat hän saa nähdä?”. Vain sovelluksen taustajärjestelmän pääsynhallintaan tarvitsemat oikeudet.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Korvaa valtuutusskeema eli resurssityypit ja kunkin suhteen määräytymissäännöt. Tämä muuttaa kaikkien tämän ympäristön käyttöoikeustarkistusten tulokset kerralla.',
    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Koko ympäristössä voimassa olevat roolit: kaikissa organisaatioissa ja myös ilman organisaatiojäsenyyttä. Organisaatiot eivät koskaan näe näitä rooleja. :part1 :part2',
    'sandbox_environment_for_testing_only_this_is_part1_your_4efdd306' => 'Testiympäristö – vain testausta varten. Tämä :part1 ole tuotantokirjautumisesi, eikä oikeita sähköpostiviestejä lähetetä.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'Scope ”:part1” on poistettu. Sen saaneet sovellukset säilyttävät sen vapaasti kirjoitettuna scopena, joka ei enää anna pääsyä tähän API:in.',
    'showing_the_first_part1_search_to_reach_the_rest_anythi_57d8cba9' => 'Ensimmäiset :part1 näytetään. Etsi loput haulla. Jo valitsemasi kohteet pysyvät luettelossa.',
    'sms_allowed_country_count' => 'Hyväksytään toiseksi tunnistustekijäksi :count maassa.|Hyväksytään toiseksi tunnistustekijäksi :count maassa.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Henkilön, joka :part1, tietoja ei koskaan lähetetä. Hänen salasanansa on Cbox ID:ssä, eikä vanha järjestelmä voi vaikuttaa siihen.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Kun henkilö kirjautuu ja on :part1, hänen sähköpostiosoitteensa ja salasanansa lähetetään kyseiseen päätepisteeseen. Jos vastaus on myönteinen, henkilö luodaan tänne eikä tietoja enää lähetetä sinne uudelleen.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Tallenna, vaihda ja peru muiden palvelujen tunnistetietoja sekä myönnä tai peru sovelluksen oikeus käyttää niitä tilapäisesti. Tämä ei koske sovelluksen oman tunnisteen käyttöoikeusalueita vault.manage / vault.lease.',
    'streamable_http_every_request_carries_part1_part2_a_man_6348600d' => 'Streamable HTTP. Jokainen pyyntö sisältää :part1 :part2 eli tämän ympäristön hallinta-avaimen.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => 'Jäitkö jumiin johonkin näistä? Konsolin jokaisella sivulla on otsikon vieressä :part1 :part2 :part3, jossa on lyhyt selitys ja linkki koko ohjeeseen.',
    'suspension_is_the_only_lever_here_and_it_is_reversible__9f87c506' => 'Täällä voit vain poistaa organisaation käytöstä tai ottaa sen uudelleen käyttöön. Mikään tällä sivulla ei poista organisaatiota tai tyhjennä sen tietoja. Asennuksessa on myös ympäristöjä, jotka eivät kuulu organisaatioon: alustan juuriympäristö ja mahdolliset irralliset ympäristöt. Ne on merkitty selvästi kohdassa :part1 :part2.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Tällä sivulla voi muuttaa vain käytöstäpoiston tilaa, ja muutoksen voi perua. Ympäristön valitseminen ja avaaminen vaihtaa vain hallintakonsolin näkymää. Kumpaakaan ympäristöä ei muuteta.',
    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'Tekstiviestikoodit numeroon :part1 lakkaavat toimimasta. Tunnistautumissovellus, pääsyavaimet ja palautuskoodit eivät muutu. Jos puhelinnumero oli henkilön ainoa toinen tunnistautumistekijä, tiliä suojaa vain salasana, kunnes uusi tekijä otetaan käyttöön.',
    'that_certificate_has_already_expired_part1_download_the_9adb4bed' => 'Varmenne on jo vanhentunut (:part1). Lataa voimassa oleva varmenne identiteetintarjoajaltasi.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Tätä selainkuvaketta ei voi käyttää. Lähetä itse kuva base64-koodattuna data:-URI:na (data:image/png;base64,…). Ulkoisia kuvien URL-osoitteita ei hyväksytä. Jokainen kävijä lataa kirjautumissivun kuvan, jolloin ulkoinen kuvapalvelin saisi tietoja kävijöistä.',
    'that_is_a_lot_of_emails_try_again_in_part1_seconds_or_c_1e69af47' => 'Sähköpostiviestejä on pyydetty paljon. Yritä uudelleen :part1 sekunnin kuluttua tai tarkista sillä välin roskapostikansiosi.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'Kaikki luettelon tehtävät ovat nyt valmiit. Jatkossa palaat hallintakonsoliin lähinnä tarpeen mukaan. Kaksi osiota kannattaa tarkistaa säännöllisesti: :part1 :part2 :part3 ja :part4 :part5 :part6.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Tätä logoa ei voi käyttää. Lähetä itse kuva base64-koodattuna data:-URI:na (data:image/png;base64,…). Ulkoisia kuvien URL-osoitteita ei hyväksytä. Jokainen kävijä lataa kirjautumissivun kuvan, jolloin ulkoinen kuvapalvelin saisi tietoja kävijöistä.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'Sähköpostiverkkotunnukset, joiden omistusta organisaatiosi ovat ilmoittaneet. Vahvistettu verkkotunnus ohjaa kaikki sen osoitteita käyttävät organisaation yhteyteen: :part1 :part2. Kukin verkkotunnus vahvistetaan organisaation sivulla.',
    'the_platform_s_own_environment_on_part1_how_every_organ_acd123ad' => 'Alustan oma ympäristö osoitteessa :part1: sen kautta organisaatioiden omistajat ja alustan ylläpitäjät kirjautuvat Cbox ID:hen sekä kaikkien ympäristöjen hallintakonsoleihin. Täällä tehty muutos koskee kaikkia näitä kirjautumisia.',
    'the_role_part1_cannot_be_held_in_this_organization_it_b_6fdeacd4' => 'Roolia [:part1] ei voi antaa tässä organisaatiossa. Se kuuluu toiseen organisaatioon tai sovellukseen, jota tämä organisaatio ei saa käyttää.',
    'there_is_no_client_secret_to_paste_part1_expects_a_sign_574fe375' => 'Liitettävää asiakassalaisuutta ei ole. :part1 edellyttää sen sijaan allekirjoitettua vakuutusta, jonka luomme yllä olevalla avaimella jokaista kirjautumista varten ja uusimme hyvissä ajoin ennen sen vanhenemista.',
    'there_is_no_role_to_grant_yet_define_one_on_the_part1_p_ffe056a6' => 'Myönnettävää roolia ei vielä ole. Määritä rooli sivulla :part1 :part2 :part3 tai anna sovelluksen ilmoittaa omat roolinsa manifestissaan.',
    'these_are_the_buttons_on_part1_how_every_organization_o_ca549807' => 'Nämä ovat sivun :part1 painikkeet, joilla organisaatioiden omistajat ja alustan ylläpitäjät kirjautuvat Cbox ID:hen ja siten kaikkien ympäristöjen hallintakonsoleihin. Niiden ylläpitäjät käyttävät Cbox ID -tilejä. Rekisteröi kullekin palveluntarjoajalle näytetty uudelleenohjaus-URI kyseisen palveluntarjoajan asetuksiin. Löydät sen kohdasta :part2 :part3.',
    'these_buttons_are_for_the_people_who_sign_in_to_your_ap_580f5efd' => 'Nämä painikkeet ovat sovelluksiisi kirjautuville käyttäjille kohteen :part1 :part2 kirjautumissivuilla. :part3',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Henkilöstä tulee kohteen :part1 omistaja ja sinusta ylläpitäjä. Vain uusi omistaja voi siirtää omistajuuden takaisin.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Sovelluksella on usean API:n käyttöoikeusalueita: :part1 :part2. Tunniste koskee kerrallaan yhtä API:a, joten sovellus nimeää haluamansa API:n parametrilla :part3. Kahden API:n käyttöoikeusalueita samanaikaisesti pyytävä pyyntö hylätään.',
    'this_console_is_your_organization_its_projects_team_key_15ebbd0f' => 'Tämä hallintakonsoli on organisaatiosi: sen projektit, tiimi, avaimet ja laskutus. Sovellustesi kirjautumistavat, myös sovelluksen :part1, määritetään ympäristökohtaisesti kunkin ympäristön hallintakonsolissa.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Tämä tunnistetieto edellyttää henkilön hyväksyntää toiminnolle, mutta hyväksyjää ei ole rekisteröity. Suorita toiminto hallintakonsolissa tai luo siellä avain, jonka omistaja voi antaa hyväksynnän.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Tämä asennus lähettää tekstiviestejä vain kohteeseen :part1. Kohteen :part2 numerot eivät siksi voi vastaanottaa koodeja, ennen kuin ne sisältyvät asetukseen CBOX_ID_SMS_ALLOWED_COUNTRIES.',
    'this_environment_s_issuer_discovery_and_jwks_are_served_06e9c844' => 'Tämän ympäristön myöntäjä, discovery ja JWKS ovat saatavilla osoitteessa :part1 :part2. Ohjaa isäntänimi ingressiisi ja päätä TLS-yhteys siellä.',
    'this_environment_s_own_issuer_what_an_sdk_discovers_fro_b00e706b' => 'Ympäristön oma myöntäjä: osoite, josta SDK hakee määritykset ja joka sisältyy väitteeseen :part1.',
    'this_person_is_the_only_owner_of_part1_organization_s_p_662dfa99' => 'Tämä henkilö on ainoa omistaja :part1 organisaatiossa: :part2. Siirrä omistajuus ennen henkilön poistamista.',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Vapaasti kirjoitetuilla scopeilla (:part1) ei ole omistajaa. Ne välitetään sellaisinaan, eivätkä ne koskaan käytä rekisteröityä API:a kohdeyleisönään.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'Sähköpostia ei voitu lähettää juuri nyt, koska asennus ei saa yhteyttä sähköpostipalvelimeensa. Yritä myöhemmin uudelleen. Ylläpitäjä voi myös vahvistaa osoitteesi komennolla `php artisan cbox-id:users:confirm-email`.',
    'we_have_sent_a_few_links_already_try_again_in_part1_sec_a84fe552' => 'Olemme jo lähettäneet useita linkkejä. Yritä uudelleen :part1 sekunnin kuluttua tai tarkista sillä välin roskapostikansiosi.',
    'we_sent_a_link_to_part1_your_first_environment_your_liv_9786541d' => 'Lähetimme linkin osoitteeseen :part1. Kun avaat sen, ensimmäinen ympäristösi luodaan: tuotantokäyttöön tarkoitettu identiteetintarjoajasi, jolla on oma kirjautuminen, käyttäjät ja allekirjoitusavaimet. Palaat sitten suoraan tänne. Linkki on voimassa 24 tuntia.',
    'which_of_its_actions_wait_for_a_person_the_agent_gets_a_e72df5dd' => 'Toiminnot, jotka odottavat hyväksyntää. Agentti saa 202-vastauksen ja lyhyen koodin. Hyväksyt toiminnon puhelimellasi tai kohdassa :part1 :part2, minkä jälkeen agentti toistaa pyynnön yhden kerran.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Kirjoita ja poista suhdetupleja: kuka omistaa mitäkin sovelluksesi resurssia ja kuka saa muokata tai katsella sitä. Sovelluksen käyttöoikeus myönnetään tai perutaan heti muutoksen tallentuessa.',
    'you_are_signed_in_part1_but_your_account_does_not_admin_1a2cb08a' => 'Olet kirjautunut :part1, mutta tilisi ei voi hallita kohdetta :part2. Ympäristön hallintakonsolin voivat avata sen organisaation omistajat, ylläpitäjät ja kehittäjät.',
    'you_have_no_environment_to_open_yet_part1_part2_part3_t_3a10832d' => 'Sinulla ei vielä ole avattavaa ympäristöä. Luo ympäristö kohdassa :part1 :part2 :part3 tai pyydä pääsyä organisaation omistajalta.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'Kirjautumissivulle lisätään Luo tili -linkki, ja sovellukset voivat ohjata käyttäjät suoraan rekisteröitymään parametrilla :part1.',
